definicion_sql:
BEGIN
    DECLARE v_process_start_date DATE;
    DECLARE v_process_end_date DATE;
    DECLARE v_process_date_loop DATE;
    DECLARE v_date_suffix_start STRING;
    DECLARE v_date_suffix_end STRING;
    DECLARE v_script STRING;
    DECLARE v_exists_item_params STRING;
    DECLARE v_exists_collected_traffic_source STRING;
    DECLARE v_exists_is_active_user STRING;
    DECLARE v_scritp_item_params STRING;
    DECLARE v_dataset_id_raw_event STRING;
    DECLARE v_script_collected_traffic_source STRING;
    DECLARE v_script_web_info_hostname STRING;
    DECLARE v_exists_is_hostname STRING;
    DECLARE v_script_is_active_user STRING;
    DECLARE v_exists_traffic_source STRING;
    DECLARE v_script_traffic_source STRING;
    DECLARE v_exists_traffic_medium STRING;
    DECLARE v_script_traffic_medium STRING;
    DECLARE v_exists_traffic_name STRING;
    DECLARE v_script_traffic_name STRING;
    DECLARE v_exists_source_last_click_source STRING;
    DECLARE v_script_last_click_source STRING;
    DECLARE v_exists_source_last_click_medium STRING;
    DECLARE v_script_last_click_medium STRING;
    DECLARE v_exists_source_last_click_name STRING;
    DECLARE v_script_last_click_name STRING;
    DECLARE v_exists_session_traffic_source_last_click STRING;
    DECLARE v_script_session_traffic_source_last_click STRING;
    DECLARE v_exists_session_traffic_source_last_click_tt STRING;
    DECLARE v_script_session_traffic_source_last_click_tt STRING;
    DECLARE v_exists_publisher STRING;
    DECLARE v_script_publisher STRING;
    DECLARE v_exists_batch_event_index STRING;
    DECLARE v_script_batch_event_index STRING;
    DECLARE v_exists_batch_page_id STRING;
    DECLARE v_script_batch_page_id STRING;
    DECLARE v_exists_batch_ordering_id STRING;
    DECLARE v_script_batch_ordering_id STRING;
    DECLARE v_exists_manual_source_platform STRING;
    DECLARE v_script_manual_source_platform STRING;
    DECLARE v_exists_manual_creative_format STRING;
    DECLARE v_script_manual_creative_format STRING;
    DECLARE v_exists_manual_marketing_tactic STRING;
    DECLARE v_script_manual_marketing_tactic STRING;
        
    DECLARE v_exists_cross_channel_campaign STRING;
    DECLARE v_script_cross_channel_campaign STRING;
    DECLARE v_exists_sa360_campaign STRING;
    DECLARE v_script_sa360_campaign STRING;
    DECLARE v_exists_cm360_campaign STRING;
    DECLARE v_script_cm360_campaign STRING;
    DECLARE v_exists_dv360_campaign STRING;
    DECLARE v_script_dv360_campaign STRING;
    DECLARE v_exists_manual_campaign STRING;
    DECLARE v_script_manual_campaign STRING;
    DECLARE v_exists_google_ads_campaign STRING;
    DECLARE v_script_google_ads_campaign STRING;

    DECLARE v_array_date ARRAY<DATE>;
 
    SET v_process_start_date = CASE
        WHEN CAST(NULLIF(p_process_start_date,'') AS DATE) IS NULL THEN CURRENT_DATE('America/Lima') - 15
        ELSE CAST(p_process_start_date AS DATE)
    END;
 
    SET v_process_end_date = CASE
        WHEN CAST(NULLIF(p_process_end_date,'') AS DATE) IS NULL THEN CURRENT_DATE('America/Lima') - 1
        ELSE CAST(p_process_end_date AS DATE)
    END;
 
    SET v_array_date = (SELECT GENERATE_DATE_ARRAY(v_process_start_date, v_process_end_date) process_date);
 
    FOR record IN (SELECT * FROM UNNEST(v_array_date))
    DO
        SET v_date_suffix_end = FORMAT_DATE('%Y%m%d', record.f0_);
        SET v_process_date_loop = record.f0_;
 
       EXECUTE IMMEDIATE CONCAT(
            "DELETE FROM `", p_table_master_t_event, "` ",
            "WHERE process_date = '", v_process_date_loop, "' AND itc_company_id ='", p_itc_company_id, "' AND ",
            IF(p_business_unit_id IS NULL, "business_unit_id IS NULL", CONCAT("business_unit_id='", p_business_unit_id, "'")),
            ";"
        );
 
 
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='items' AND data_type LIKE '%item_params%'"
        ) INTO v_exists_item_params;
 
 
        IF v_exists_item_params = 'SI' THEN
            SET v_scritp_item_params = ' a.items ';
        ELSE
            SET v_scritp_item_params = '''
                 ARRAY ( SELECT AS STRUCT
                    item_id ,
                    item_name ,
                    item_brand ,
                    item_variant ,
                    item_category ,
                    item_category2 ,
                    item_category3 ,
                    item_category4 ,
                    item_category5 ,
                    price_in_usd ,
                    price ,
                    quantity ,
                    item_revenue_in_usd ,
                    item_revenue ,
                    item_refund_in_usd ,
                    item_refund ,
                    coupon ,
                    affiliation ,
                    location_id ,
                    item_list_id ,
                    item_list_name ,
                    item_list_index ,
                    promotion_id ,
                    promotion_name ,
                    creative_name ,
                    creative_slot ,
                    ARRAY<STRUCT<key STRING, value STRUCT<string_value STRING, int_value INT64, float_value FLOAT64, double_value FLOAT64 >>>[
                        (CAST(NULL AS STRING), (CAST(NULL AS STRING), CAST(NULL AS INT64), CAST(NULL AS FLOAT64), CAST(NULL AS FLOAT64)) )]
                    FROM UNNEST(items) AS it
                )  AS item_params
            ''';
        END IF;
 
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='collected_traffic_source' "
        ) INTO v_exists_collected_traffic_source;
 
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='batch_event_index' "
        ) INTO v_exists_batch_event_index;

        IF v_exists_batch_event_index = 'SI' THEN
            SET v_script_batch_event_index = 'a.batch_event_index';
        ELSE
            SET v_script_batch_event_index = 'CAST(NULL AS INT64) AS batch_event_index';
        END IF;

        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='batch_page_id' "
        ) INTO v_exists_batch_page_id;

        IF v_exists_batch_page_id = 'SI' THEN
            SET v_script_batch_page_id = 'a.batch_page_id';
        ELSE
            SET v_script_batch_page_id = 'CAST(NULL AS INT64) AS batch_page_id';
        END IF;

        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='batch_ordering_id' "
        ) INTO v_exists_batch_ordering_id;  

        IF v_exists_batch_ordering_id = 'SI' THEN
            SET v_script_batch_ordering_id = 'a.batch_ordering_id';
        ELSE
            SET v_script_batch_ordering_id = 'CAST(NULL AS INT64) AS batch_ordering_id';
        END IF;

        -- Validación de manual_source_platform
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='manual_source_platform' "
        ) INTO v_exists_manual_source_platform;

        IF v_exists_manual_source_platform = 'SI' THEN
            SET v_script_manual_source_platform = 'a.collected_traffic_source.manual_source_platform';
        ELSE
            SET v_script_manual_source_platform = 'CAST(NULL AS STRING)';  
        END IF;

        -- Validación de manual_creative_format
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='manual_creative_format' "
        ) INTO v_exists_manual_creative_format;

        IF v_exists_manual_creative_format = 'SI' THEN
            SET v_script_manual_creative_format = 'a.collected_traffic_source.manual_creative_format';
        ELSE
            SET v_script_manual_creative_format = 'CAST(NULL AS STRING)';
        END IF;

        -- Validación de manual_marketing_tactic
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='manual_marketing_tactic' "
        ) INTO v_exists_manual_marketing_tactic;

        IF v_exists_manual_marketing_tactic = 'SI' THEN
            SET v_script_manual_marketing_tactic = 'a.collected_traffic_source.manual_marketing_tactic';
        ELSE
            SET v_script_manual_marketing_tactic = 'CAST(NULL AS STRING)';
        END IF;

        -- Construcción final del STRUCT con las validaciones aplicadas
        IF v_exists_collected_traffic_source = 'SI' THEN
            SET v_script_collected_traffic_source =
                ' STRUCT(a.collected_traffic_source.manual_campaign_id, ' ||
                'a.collected_traffic_source.manual_campaign_name, a.collected_traffic_source.manual_source, ' ||
                'a.collected_traffic_source.manual_medium, a.collected_traffic_source.manual_term, ' ||
                'a.collected_traffic_source.manual_content, ' ||
                v_script_manual_source_platform || ', ' ||
                v_script_manual_creative_format || ', ' ||
                v_script_manual_marketing_tactic || ', ' ||
                'a.collected_traffic_source.gclid, a.collected_traffic_source.dclid, a.collected_traffic_source.srsltid) AS collected_traffic_source';
        ELSE
            SET v_script_collected_traffic_source =
                'STRUCT<manual_campaign_id STRING, manual_campaign_name STRING, manual_source STRING, ' ||
                'manual_medium STRING, manual_term STRING, manual_content STRING, ' ||
                'manual_source_platform STRING, ' ||
                'manual_creative_format STRING, ' ||
                'manual_marketing_tactic STRING, ' || 
                'gclid STRING, dclid STRING, ' ||
                'srsltid STRING> (' ||
                'CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), ' ||
                'CAST(NULL AS STRING), CAST(NULL AS STRING), ' ||
                v_script_manual_source_platform || ', ' ||
                v_script_manual_creative_format || ', ' ||
                v_script_manual_marketing_tactic || ', ' ||
                'CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING)) AS collected_traffic_source';
        END IF;


 
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='is_active_user' "
        ) INTO v_exists_is_active_user;
 
 
 
        IF v_exists_is_active_user = 'SI' THEN
            SET v_script_is_active_user = ' a.is_active_user ';
        ELSE
            SET v_script_is_active_user = ' CAST(NULL AS BOOL) AS is_active_user';
        END IF;
 
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='device' ",
            "AND field_path = 'device.web_info.hostname' "
        ) INTO v_exists_is_hostname;
 
        IF v_exists_is_hostname = 'SI' THEN
            SET v_script_web_info_hostname = 'a.device.web_info.hostname AS web_info_hostname';
        ELSE
            SET v_script_web_info_hostname = 'CAST(NULL AS STRING) AS web_info_hostname';
        END IF;
 
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='traffic_source' ",
            "AND field_path = 'traffic_source.source' "
        ) INTO v_exists_traffic_source ;
 
        IF v_exists_traffic_source = 'SI' THEN
            SET v_script_traffic_source = 'a.traffic_source.source AS source_first_click';
        ELSE
            SET v_script_traffic_source = 'CAST(NULL AS STRING) AS source_first_click';
        END IF;
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='traffic_source' ",
            "AND field_path = 'traffic_source.medium' "
        ) INTO v_exists_traffic_medium ;
 
        IF v_exists_traffic_medium = 'SI' THEN
            SET v_script_traffic_medium = 'a.traffic_source.medium AS medium_first_click';
        ELSE
            SET v_script_traffic_medium = 'CAST(NULL AS STRING) AS medium_first_click';
        END IF;
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='traffic_source' ",
            "AND field_path = 'traffic_source.name' "
        ) INTO v_exists_traffic_name ;
 
        IF v_exists_traffic_name = 'SI' THEN
            SET v_script_traffic_name = 'a.traffic_source.name AS campaign_first_click';
        ELSE
            SET v_script_traffic_name = 'CAST(NULL AS STRING) AS campaign_first_click';
        END IF;
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' "
        ) INTO v_exists_session_traffic_source_last_click;
 
 
        IF v_exists_session_traffic_source_last_click = 'SI' THEN
            SET v_script_session_traffic_source_last_click = 'a.session_traffic_source_last_click';
        ELSE
            SET v_script_session_traffic_source_last_click = 'CAST(NULL AS STRING) AS session_traffic_source_last_click';
        END IF;
       
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path = 'session_traffic_source_last_click.manual_campaign.source' "
        ) INTO v_exists_source_last_click_source ;
 
        IF v_exists_source_last_click_source = 'SI' THEN
            SET v_script_last_click_source = 'a.session_traffic_source_last_click.manual_campaign.source AS source_last_click';
        ELSE
            SET v_script_last_click_source = 'CAST(NULL AS STRING) AS source_last_click';
        END IF;
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path = 'session_traffic_source_last_click.manual_campaign.source' "
        ) INTO v_exists_source_last_click_medium ;
 
        IF v_exists_source_last_click_medium = 'SI' THEN
            SET v_script_last_click_medium = 'a.session_traffic_source_last_click.manual_campaign.medium AS medium_last_click';
        ELSE
            SET v_script_last_click_medium = 'CAST(NULL AS STRING) AS medium_last_click';
        END IF;
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path = 'session_traffic_source_last_click.manual_campaign.source' "
        ) INTO v_exists_source_last_click_name ;
 
        IF v_exists_source_last_click_name = 'SI' THEN
            SET v_script_last_click_name = 'a.session_traffic_source_last_click.manual_campaign.campaign_name AS campaign_last_click';
        ELSE
            SET v_script_last_click_name = 'CAST(NULL AS STRING) AS campaign_last_click';
        END IF;

        -- Validación de session_traffic_source_last_click
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' "
        ) INTO v_exists_session_traffic_source_last_click_tt;

        -- Validación de manual_campaign
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path='session_traffic_source_last_click.manual_campaign' "
        ) INTO v_exists_manual_campaign;

        IF v_exists_manual_campaign = 'SI' THEN
            SET v_script_manual_campaign = 'a.session_traffic_source_last_click.manual_campaign';
        ELSE
            SET v_script_manual_campaign = 
                'CAST(NULL AS STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, term STRING, content STRING, source_platform STRING, creative_format STRING, marketing_tactic STRING>)';
        END IF;

        -- Validación de google_ads_campaign
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path='session_traffic_source_last_click.google_ads_campaign' "
        ) INTO v_exists_google_ads_campaign;

        IF v_exists_google_ads_campaign = 'SI' THEN
            SET v_script_google_ads_campaign = 'a.session_traffic_source_last_click.google_ads_campaign';
        ELSE
            SET v_script_google_ads_campaign = 
                'CAST(NULL AS STRUCT<customer_id STRING, account_name STRING, campaign_id STRING, campaign_name STRING, ad_group_id STRING, ad_group_name STRING>)';
        END IF;

        -- Validación de cross_channel_campaign
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path='session_traffic_source_last_click.cross_channel_campaign' "
        ) INTO v_exists_cross_channel_campaign;

        IF v_exists_cross_channel_campaign = 'SI' THEN
            SET v_script_cross_channel_campaign = 'a.session_traffic_source_last_click.cross_channel_campaign';
        ELSE
            SET v_script_cross_channel_campaign = 
                'CAST(NULL AS STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, source_platform STRING, default_channel_group STRING, primary_channel_group STRING>)';
        END IF;

        -- Validación de sa360_campaign
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path='session_traffic_source_last_click.sa360_campaign' "
        ) INTO v_exists_sa360_campaign;

        IF v_exists_sa360_campaign = 'SI' THEN
            SET v_script_sa360_campaign = 'a.session_traffic_source_last_click.sa360_campaign';
        ELSE
            SET v_script_sa360_campaign = 
                'CAST(NULL AS STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, ad_group_id STRING, ad_group_name STRING, creative_format STRING, engine_account_name STRING, engine_account_type STRING, manager_account_name STRING>)';
        END IF;

        -- Validación de cm360_campaign
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path='session_traffic_source_last_click.cm360_campaign' "
        ) INTO v_exists_cm360_campaign;

        IF v_exists_cm360_campaign = 'SI' THEN
            SET v_script_cm360_campaign = 'a.session_traffic_source_last_click.cm360_campaign';
        ELSE
            SET v_script_cm360_campaign = 
                'CAST(NULL AS STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, account_id STRING, account_name STRING, advertiser_id STRING, advertiser_name STRING, creative_id STRING, creative_format STRING, creative_name STRING, creative_type STRING, creative_type_id STRING, creative_version STRING, placement_id STRING, placement_cost_structure STRING, placement_name STRING, rendering_id STRING, site_id STRING, site_name STRING>)';
        END IF;

        -- Validación de dv360_campaign
        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMN_FIELD_PATHS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='session_traffic_source_last_click' ",
            "AND field_path='session_traffic_source_last_click.dv360_campaign' "
        ) INTO v_exists_dv360_campaign;

        IF v_exists_dv360_campaign = 'SI' THEN
            SET v_script_dv360_campaign = 'a.session_traffic_source_last_click.dv360_campaign';
        ELSE
            SET v_script_dv360_campaign = 
                'CAST(NULL AS STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, advertiser_id STRING, advertiser_name STRING, creative_id STRING, creative_format STRING, creative_name STRING, exchange_id STRING, exchange_name STRING, insertion_order_id STRING, insertion_order_name STRING, line_item_id STRING, line_item_name STRING, partner_id STRING, partner_name STRING>)';
        END IF;

        -- Construcción del STRUCT session_traffic_source_last_click
        IF v_exists_session_traffic_source_last_click_tt = 'SI' THEN
            SET v_script_session_traffic_source_last_click_tt =
                'STRUCT(' ||
                v_script_manual_campaign || ', ' ||
                v_script_google_ads_campaign || ', ' ||
                v_script_cross_channel_campaign || ', ' ||
                v_script_sa360_campaign || ', ' || 
                v_script_cm360_campaign || ', ' ||
                v_script_dv360_campaign ||
                ') AS session_traffic_source_last_click';
        ELSE
            SET v_script_session_traffic_source_last_click_tt =
                'STRUCT< ' ||
                'manual_campaign STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, term STRING, content STRING, source_platform STRING, creative_format STRING, marketing_tactic STRING>, ' ||
                'google_ads_campaign STRUCT<customer_id STRING, account_name STRING, campaign_id STRING, campaign_name STRING, ad_group_id STRING, ad_group_name STRING>, ' ||
                'cross_channel_campaign STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, source_platform STRING, default_channel_group STRING, primary_channel_group STRING>, ' ||
                'sa360_campaign STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, ad_group_id STRING, ad_group_name STRING, creative_format STRING, engine_account_name STRING, engine_account_type STRING, manager_account_name STRING>, ' ||
                'cm360_campaign STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, account_id STRING, account_name STRING, advertiser_id STRING, advertiser_name STRING, creative_id STRING, creative_format STRING, creative_name STRING, creative_type STRING, creative_type_id STRING, creative_version STRING, placement_id STRING, placement_cost_structure STRING, placement_name STRING, rendering_id STRING, site_id STRING, site_name STRING>, ' ||
                'dv360_campaign STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, advertiser_id STRING, advertiser_name STRING, creative_id STRING, creative_format STRING, creative_name STRING, exchange_id STRING, exchange_name STRING, insertion_order_id STRING, insertion_order_name STRING, line_item_id STRING, line_item_name STRING, partner_id STRING, partner_name STRING> ' ||
                '> (' ||
                'CAST(NULL AS STRUCT<campaign_id STRING, campaign_name STRING, source STRING, medium STRING, term STRING, content STRING, source_platform STRING, creative_format STRING, marketing_tactic STRING>), ' ||
                'CAST(NULL AS STRUCT<customer_id STRING, account_name STRING, campaign_id STRING, campaign_name STRING, ad_group_id STRING, ad_group_name STRING>), ' ||
                v_script_cross_channel_campaign || ', ' ||
                v_script_sa360_campaign || ', ' ||
                v_script_cm360_campaign || ', ' ||
                v_script_dv360_campaign ||
                ') AS session_traffic_source_last_click';
        END IF;


        EXECUTE IMMEDIATE CONCAT(
            "SELECT CASE WHEN COUNT(1) > 0 THEN 'SI' ELSE 'NO' END ",
            "FROM `", p_dataset_id_raw_event, ".INFORMATION_SCHEMA.COLUMNS` ",
            "WHERE table_name ='", p_table_name_raw_event, "_", v_date_suffix_end, "' ",
            "AND column_name='publisher' "
        ) INTO v_exists_publisher;

        IF v_exists_publisher = 'SI' THEN
            SET v_script_publisher = 'a.publisher';
        ELSE
            SET v_script_publisher =
                'STRUCT<ad_revenue_in_usd FLOAT64, ad_format STRING, ad_source_name STRING, ad_unit_id STRING> (' ||
                'CAST(NULL AS FLOAT64), CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING)) AS publisher';
        END IF;

 
 
 
        SET v_script = '''
            INSERT INTO `''' || p_table_master_t_event || '''` (
                process_date, itc_company_id, itc_company_name, business_unit_id, business_unit, party_id, event_date,
                event_timestamp, event_name, event_params, event_previous_timestamp, event_value_in_usd, event_bundle_sequence_id,
                event_server_timestamp_offset, user_id, user_pseudo_id, privacy_info, user_properties, user_first_touch_timestamp,
                user_ltv, device, geo, app_info, traffic_source, stream_id, platform, event_dimensions, ecommerce, items,
                collected_traffic_source, is_active_user, record_source, load_date, creation_user, hash_id, hash_email,hash_mobile1,hash_mobile2,hash_dni,itc_clientid,google_clientid,digital_party_id,
                web_info_hostname,source_first_click,medium_first_click,campaign_first_click,source_last_click,medium_last_click,
                campaign_last_click,session_traffic_source_last_click,publisher,batch_event_index,batch_page_id,batch_ordering_id,ga_session_id,ga_session_number
               
            )
            WITH iden_party AS (
                SELECT * EXCEPT(rank) FROM (
                    SELECT UPPER(hash_id) AS hash_id, party_id,
                        ROW_NUMBER() OVER(PARTITION BY UPPER(hash_id) ORDER BY process_date DESC, party_id DESC) AS rank
                    FROM `''' || p_table_iden_party || '''`
                ) WHERE rank = 1
            ),
            iden_party_corto AS (
                SELECT UPPER(SUBSTRING(hash_id, 1, 36)) AS hash_id_corto, MAX(party_id) AS party_id, COUNT(1) AS cant
                FROM `''' || p_table_iden_party || '''`
                GROUP BY hash_id_corto
                HAVING cant = 1
            ),
            contact AS (
                SELECT * EXCEPT(rank) FROM (
                    SELECT hash_email, party_id,
                        ROW_NUMBER() OVER(PARTITION BY hash_email ORDER BY process_date DESC, party_id DESC) AS rank
                    FROM `''' || p_table_ba_contact_info || '''`
                ) WHERE rank = 1
            ),
            event_aux AS (
                SELECT
                    event_date,
                    event_timestamp,
                    event_name,
                    event_params,
                    event_previous_timestamp,
                    event_value_in_usd,
                    event_bundle_sequence_id,
                    event_server_timestamp_offset,
                    user_id,
                    user_pseudo_id,
                    privacy_info,
                    user_properties,
                    user_first_touch_timestamp,
                    user_ltv,
                    device,
                    geo,
                    app_info,
                    traffic_source,
                    stream_id,
                    platform,
                    event_dimensions,
                    ecommerce, 
                    ''' || (IF(v_exists_session_traffic_source_last_click_tt = 'SI', 'session_traffic_source_last_click', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_event_index = 'SI', 'batch_event_index', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_page_id = 'SI', 'batch_page_id', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_ordering_id = 'SI', 'batch_ordering_id', "''")) || ''' ,
                    ''' || (IF(v_exists_publisher = 'SI', 'publisher', "''")) || ''' ,
                    items,
                    ''' || (IF(v_exists_collected_traffic_source = 'SI', 'collected_traffic_source', "''")) || ''' ,
                    ''' || (IF(v_exists_is_active_user = 'SI', 'is_active_user', "''")) || ''',
                    (SELECT AS VALUE a.value.string_value
                    FROM UNNEST(user_properties) AS a
                    WHERE a.key = ''' || "'" || p_user_properties_hash_id || "'" || ''') AS event_user_hash_id,
                    (SELECT AS VALUE a.value.string_value
                    FROM UNNEST(user_properties) AS a
                    WHERE a.key = ''' || "'" || p_user_properties_hash_email || "'" || ''') AS event_user_hash_email,
 
                    (SELECT AS VALUE trim(CONCAT(
                        IFNULL(CAST(a.value.string_value AS STRING), ''),
                        IFNULL(CAST(a.value.int_value AS STRING), ''),
                        IFNULL(CAST(a.value.float_value AS STRING), ''),
                        IFNULL(CAST(a.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS a
                    WHERE a.key = ''' || "'" || p_event_params_hash_id || "'" || ''') AS event_params_hash_id,
 
                    (SELECT AS VALUE trim(CONCAT(
                        IFNULL(CAST(a.value.string_value AS STRING), ''),
                        IFNULL(CAST(a.value.int_value AS STRING), ''),
                        IFNULL(CAST(a.value.float_value AS STRING), ''),
                        IFNULL(CAST(a.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS a
                    WHERE a.key = ''' || "'" || p_event_params_hash_email || "'" || ''') AS event_params_hash_email ,
 
                    /* Obtener event_user_hash_celular1 */
                    (SELECT AS VALUE c.value.string_value
                    FROM UNNEST(user_properties) AS c
                    WHERE c.key = ''' || "'" || p_user_properties_hash_celular1 || "'" || ''') AS event_user_hash_celular1,
 
                    /* Obtener event_params_hash_celular1 */
                    (SELECT AS VALUE TRIM(CONCAT(
                        IFNULL(CAST(d.value.string_value AS STRING), ''),
                        IFNULL(CAST(d.value.int_value AS STRING), ''),
                        IFNULL(CAST(d.value.float_value AS STRING), ''),
                        IFNULL(CAST(d.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS d
                    WHERE d.key = ''' || "'" || p_user_properties_hash_celular1 || "'" || ''') AS event_params_hash_celular1,
                    /* Obtener event_user_hash_celular2  */
                    (SELECT AS VALUE e.value.string_value
                    FROM UNNEST(user_properties) AS e
                    WHERE e.key = ''' || "'" || p_user_properties_hash_celular2 || "'" || ''') AS event_user_hash_celular2,
 
                    /* Obtener event_params_hash_celular2 */
                    (SELECT AS VALUE TRIM(CONCAT(
                        IFNULL(CAST(f.value.string_value AS STRING), ''),
                        IFNULL(CAST(f.value.int_value AS STRING), ''),
                        IFNULL(CAST(f.value.float_value AS STRING), ''),
                        IFNULL(CAST(f.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS f
                    WHERE f.key = ''' || "'" || p_user_properties_hash_celular2 || "'" || ''') AS event_params_hash_celular2,
                    /* Obtener event_user_hash_dni */
                    (SELECT AS VALUE g.value.string_value
                    FROM UNNEST(user_properties) AS g
                    WHERE g.key = ''' || "'" || p_user_properties_hash_dni || "'" || ''') AS event_user_hash_dni,
 
                    /* Obtener event_params_hash_dni  */
                    (SELECT AS VALUE TRIM(CONCAT(
                        IFNULL(CAST(h.value.string_value AS STRING), ''),
                        IFNULL(CAST(h.value.int_value AS STRING), ''),
                        IFNULL(CAST(h.value.float_value AS STRING), ''),
                        IFNULL(CAST(h.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS h
                    WHERE h.key = ''' || "'" || p_user_properties_hash_dni || "'" || ''') AS event_params_hash_dni,
 
                    /* Obtener event_user_itc_clientid */
                    (SELECT AS VALUE a.value.string_value
                    FROM UNNEST(user_properties) AS a
                    WHERE a.key = ''' || "'" || p_user_properties_itc_clientid || "'" || ''') AS event_user_itc_clientid,
                    (SELECT value.int_value  FROM UNNEST(event_params) WHERE key = 'ga_session_id') AS ga_session_id,
                    (SELECT value.int_value  FROM UNNEST(event_params)  WHERE key = 'ga_session_number') AS ga_session_number
                FROM
                    `''' || p_dataset_id_raw_event || '.' || p_table_name_raw_event || '_' || v_date_suffix_end || '''`
            ),
            event AS (
                SELECT
                    a.event_date,
                    a.event_timestamp,
                    a.event_name,
                    a.event_params,
                    a.event_previous_timestamp,
                    a.event_value_in_usd,
                    a.event_bundle_sequence_id,
                    a.event_server_timestamp_offset,
                    a.user_id,
                    a.user_pseudo_id,
                    a.privacy_info,
                    a.user_properties,
                    a.user_first_touch_timestamp,
                    a.user_ltv,
                    a.device,
                    a.geo,
                    a.app_info,
                    a.traffic_source,
                    a.stream_id,
                    a.platform,
                    a.event_dimensions,
                    a.ecommerce,
                    a.items,
                    ''' || (IF(v_exists_collected_traffic_source = 'SI', 'a.collected_traffic_source',"''")) || ''' ,
                    ''' || (IF(v_exists_is_active_user = 'SI', 'a.is_active_user', "''")) || ''' ,
                    COALESCE(a.event_user_hash_id, a.event_params_hash_id, '') AS hash_id,
                    COALESCE(a.event_user_hash_email, a.event_params_hash_email, user_id,'') AS hash_email ,
                    COALESCE(a.event_user_hash_celular1, a.event_params_hash_celular1, '') AS hash_mobile1,
                    COALESCE(a.event_user_hash_celular2, a.event_params_hash_celular2, '') AS hash_mobile2,
                    COALESCE(a.event_user_hash_dni, a.event_params_hash_dni, '') AS hash_dni,
                    a.event_user_itc_clientid  AS itc_clientid,
                    ''' || (IF(v_exists_session_traffic_source_last_click_tt = 'SI', 'a.session_traffic_source_last_click',"''")) || ''' ,
                    ''' || (IF(v_exists_batch_event_index = 'SI', 'a.batch_event_index', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_page_id = 'SI', 'a.batch_page_id', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_ordering_id = 'SI', 'a.batch_ordering_id', "''")) || ''' ,
                    ''' || (IF(v_exists_publisher = 'SI', 'a.publisher',"''")) || ''' ,
                    a.ga_session_id,
                    a.ga_session_number
 
                FROM  
                    event_aux a
            )  
            SELECT
                PARSE_DATE('%Y%m%d', event_date) AS process_date,
                ''' || "'" || p_itc_company_id || "'" || ''' AS itc_company_id,
                ''' || "'" || p_itc_company_name || "'" || ''' AS itc_company_name,
                ''' || COALESCE(IF(p_business_unit_id IS NULL, 'CAST(NULL AS STRING)', "'" || p_business_unit_id || "'"), 'CAST(NULL AS STRING)') || ''' AS business_unit_id,
                ''' || COALESCE(IF(p_business_unit IS NULL, 'CAST(NULL AS STRING)', "'" || p_business_unit || "'"), 'CAST(NULL AS STRING)') || ''' AS business_unit,
                COALESCE(b.party_id, c.party_id) AS party_id,
                a.event_date,
                a.event_timestamp,
                a.event_name,
                a.event_params,
                a.event_previous_timestamp,
                a.event_value_in_usd,
                a.event_bundle_sequence_id,
                a.event_server_timestamp_offset,
                a.user_id,
                a.user_pseudo_id,
                a.privacy_info,
                a.user_properties,
                a.user_first_touch_timestamp,
                a.user_ltv,
                a.device,
                a.geo,
                a.app_info,
                a.traffic_source,
                a.stream_id,
                a.platform,
                a.event_dimensions,
                a.ecommerce,
                ''' || v_scritp_item_params || ''',
                ''' || v_script_collected_traffic_source || ''',
                ''' || v_script_is_active_user || ''',
                ''' || "'" || p_record_source || "'" || ''' AS record_source,
                CAST(CURRENT_DATETIME('America/Lima') AS TIMESTAMP) AS load_date,
                SESSION_USER() AS creation_user,
                a.hash_id,
                a.hash_email,
                a.hash_mobile1,
                a.hash_mobile2,
                a.hash_dni,
                a.itc_clientid ,        
                a.user_pseudo_id  AS google_clientid,
                COALESCE(a.itc_clientid,a.user_pseudo_id,'') AS digital_party_id,
                ''' || v_script_web_info_hostname || ''',
                ''' || v_script_traffic_source || ''',
                ''' || v_script_traffic_medium || ''',
                ''' || v_script_traffic_name || ''',
                ''' || v_script_last_click_source || ''',
                ''' || v_script_last_click_medium || ''',
                ''' || v_script_last_click_name || ''',
                ''' || v_script_session_traffic_source_last_click_tt || ''',
                ''' || v_script_publisher || ''',
                ''' || v_script_batch_event_index || ''',
                ''' || v_script_batch_page_id || ''',
                ''' || v_script_batch_ordering_id || ''',
                a.ga_session_id,
                a.ga_session_number
            FROM   event a
            LEFT JOIN iden_party b  ON a.hash_id = b.hash_id
            LEFT JOIN contact c    ON a.hash_email = c.hash_email  
                 
        ''';
        EXECUTE IMMEDIATE v_script;
    END FOR;
END

