                    ''' || (IF(v_exists_session_traffic_source_last_click_tt = 'SI', 'session_traffic_source_last_click', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_event_index = 'SI', 'batch_event_index', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_page_id = 'SI', 'batch_page_id', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_ordering_id = 'SI', 'batch_ordering_id', "''")) || ''' ,
                    ''' || (IF(v_exists_publisher = 'SI', 'publisher', "''")) || ''' ,
                    items,
                    ''' || (IF(v_exists_collected_traffic_source = 'SI', 'collected_traffic_source', "''")) || ''' ,
                    ''' || (IF(v_exists_is_active_user = 'SI', 'is_active_user', "''")) || ''',
                    (SELECT AS VALUE a.value.string_value
                    FROM UNNEST(user_properties) AS a
                    WHERE a.key = ''' || "'" || p_user_properties_hash_id || "'" || ''') AS event_user_hash_id,
                    (SELECT AS VALUE a.value.string_value
                    FROM UNNEST(user_properties) AS a
                    WHERE a.key = ''' || "'" || p_user_properties_hash_email || "'" || ''') AS event_user_hash_email,
 
                    (SELECT AS VALUE trim(CONCAT(
                        IFNULL(CAST(a.value.string_value AS STRING), ''),
                        IFNULL(CAST(a.value.int_value AS STRING), ''),
                        IFNULL(CAST(a.value.float_value AS STRING), ''),
                        IFNULL(CAST(a.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS a
                    WHERE a.key = ''' || "'" || p_event_params_hash_id || "'" || ''') AS event_params_hash_id,
 
                    (SELECT AS VALUE trim(CONCAT(
                        IFNULL(CAST(a.value.string_value AS STRING), ''),
                        IFNULL(CAST(a.value.int_value AS STRING), ''),
                        IFNULL(CAST(a.value.float_value AS STRING), ''),
                        IFNULL(CAST(a.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS a
                    WHERE a.key = ''' || "'" || p_event_params_hash_email || "'" || ''') AS event_params_hash_email ,
 
                    /* Obtener event_user_hash_celular1 */
                    (SELECT AS VALUE c.value.string_value
                    FROM UNNEST(user_properties) AS c
                    WHERE c.key = ''' || "'" || p_user_properties_hash_celular1 || "'" || ''') AS event_user_hash_celular1,
 
                    /* Obtener event_params_hash_celular1 */
                    (SELECT AS VALUE TRIM(CONCAT(
                        IFNULL(CAST(d.value.string_value AS STRING), ''),
                        IFNULL(CAST(d.value.int_value AS STRING), ''),
                        IFNULL(CAST(d.value.float_value AS STRING), ''),
                        IFNULL(CAST(d.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS d
                    WHERE d.key = ''' || "'" || p_user_properties_hash_celular1 || "'" || ''') AS event_params_hash_celular1,
                    /* Obtener event_user_hash_celular2  */
                    (SELECT AS VALUE e.value.string_value
                    FROM UNNEST(user_properties) AS e
                    WHERE e.key = ''' || "'" || p_user_properties_hash_celular2 || "'" || ''') AS event_user_hash_celular2,
 
                    /* Obtener event_params_hash_celular2 */
                    (SELECT AS VALUE TRIM(CONCAT(
                        IFNULL(CAST(f.value.string_value AS STRING), ''),
                        IFNULL(CAST(f.value.int_value AS STRING), ''),
                        IFNULL(CAST(f.value.float_value AS STRING), ''),
                        IFNULL(CAST(f.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS f
                    WHERE f.key = ''' || "'" || p_user_properties_hash_celular2 || "'" || ''') AS event_params_hash_celular2,
                    /* Obtener event_user_hash_dni */
                    (SELECT AS VALUE g.value.string_value
                    FROM UNNEST(user_properties) AS g
                    WHERE g.key = ''' || "'" || p_user_properties_hash_dni || "'" || ''') AS event_user_hash_dni,
 
                    /* Obtener event_params_hash_dni  */
                    (SELECT AS VALUE TRIM(CONCAT(
                        IFNULL(CAST(h.value.string_value AS STRING), ''),
                        IFNULL(CAST(h.value.int_value AS STRING), ''),
                        IFNULL(CAST(h.value.float_value AS STRING), ''),
                        IFNULL(CAST(h.value.double_value AS STRING), '')
                    ))
                    FROM UNNEST(event_params) AS h
                    WHERE h.key = ''' || "'" || p_user_properties_hash_dni || "'" || ''') AS event_params_hash_dni,
 
                    /* Obtener event_user_itc_clientid */
                    (SELECT AS VALUE a.value.string_value
                    FROM UNNEST(user_properties) AS a
                    WHERE a.key = ''' || "'" || p_user_properties_itc_clientid || "'" || ''') AS event_user_itc_clientid,
                    (SELECT value.int_value  FROM UNNEST(event_params) WHERE key = 'ga_session_id') AS ga_session_id,
                    (SELECT value.int_value  FROM UNNEST(event_params)  WHERE key = 'ga_session_number') AS ga_session_number
                FROM
                    `''' || p_dataset_id_raw_event || '.' || p_table_name_raw_event || '_' || v_date_suffix_end || '''`
            ),
            event AS (
                SELECT
                    a.event_date,
                    a.event_timestamp,
                    a.event_name,
                    a.event_params,
                    a.event_previous_timestamp,
                    a.event_value_in_usd,
                    a.event_bundle_sequence_id,
                    a.event_server_timestamp_offset,
                    a.user_id,
                    a.user_pseudo_id,
                    a.privacy_info,
                    a.user_properties,
                    a.user_first_touch_timestamp,
                    a.user_ltv,
                    a.device,
                    a.geo,
                    a.app_info,
                    a.traffic_source,
                    a.stream_id,
                    a.platform,
                    a.event_dimensions,
                    a.ecommerce,
                    a.items,
                    ''' || (IF(v_exists_collected_traffic_source = 'SI', 'a.collected_traffic_source',"''")) || ''' ,
                    ''' || (IF(v_exists_is_active_user = 'SI', 'a.is_active_user', "''")) || ''' ,
                    COALESCE(a.event_user_hash_id, a.event_params_hash_id, '') AS hash_id,
                    COALESCE(a.event_user_hash_email, a.event_params_hash_email, user_id,'') AS hash_email ,
                    COALESCE(a.event_user_hash_celular1, a.event_params_hash_celular1, '') AS hash_mobile1,
                    COALESCE(a.event_user_hash_celular2, a.event_params_hash_celular2, '') AS hash_mobile2,
                    COALESCE(a.event_user_hash_dni, a.event_params_hash_dni, '') AS hash_dni,
                    a.event_user_itc_clientid  AS itc_clientid,
                    ''' || (IF(v_exists_session_traffic_source_last_click_tt = 'SI', 'a.session_traffic_source_last_click',"''")) || ''' ,
                    ''' || (IF(v_exists_batch_event_index = 'SI', 'a.batch_event_index', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_page_id = 'SI', 'a.batch_page_id', "''")) || ''' ,
                    ''' || (IF(v_exists_batch_ordering_id = 'SI', 'a.batch_ordering_id', "''")) || ''' ,
                    ''' || (IF(v_exists_publisher = 'SI', 'a.publisher',"''")) || ''' ,
                    a.ga_session_id,
                    a.ga_session_number
 
                FROM  
                    event_aux a
            )  
            SELECT
                PARSE_DATE('%Y%m%d', event_date) AS process_date,
                ''' || "'" || p_itc_company_id || "'" || ''' AS itc_company_id,
                ''' || "'" || p_itc_company_name || "'" || ''' AS itc_company_name,
                ''' || COALESCE(IF(p_business_unit_id IS NULL, 'CAST(NULL AS STRING)', "'" || p_business_unit_id || "'"), 'CAST(NULL AS STRING)') || ''' AS business_unit_id,
                ''' || COALESCE(IF(p_business_unit IS NULL, 'CAST(NULL AS STRING)', "'" || p_business_unit || "'"), 'CAST(NULL AS STRING)') || ''' AS business_unit,
                COALESCE(b.party_id, c.party_id) AS party_id,
                a.event_date,
                a.event_timestamp,
                a.event_name,
                a.event_params,
                a.event_previous_timestamp,
                a.event_value_in_usd,
                a.event_bundle_sequence_id,
                a.event_server_timestamp_offset,
                a.user_id,
                a.user_pseudo_id,
                a.privacy_info,
                a.user_properties,
                a.user_first_touch_timestamp,
                a.user_ltv,
                a.device,
                a.geo,
                a.app_info,
                a.traffic_source,
                a.stream_id,
                a.platform,
                a.event_dimensions,
                a.ecommerce,
                ''' || v_scritp_item_params || ''',
                ''' || v_script_collected_traffic_source || ''',
                ''' || v_script_is_active_user || ''',
                ''' || "'" || p_record_source || "'" || ''' AS record_source,
                CAST(CURRENT_DATETIME('America/Lima') AS TIMESTAMP) AS load_date,
                SESSION_USER() AS creation_user,
                a.hash_id,
                a.hash_email,
                a.hash_mobile1,
                a.hash_mobile2,
                a.hash_dni,
                a.itc_clientid ,        
                a.user_pseudo_id  AS google_clientid,
                COALESCE(a.itc_clientid,a.user_pseudo_id,'') AS digital_party_id,
                ''' || v_script_web_info_hostname || ''',
                ''' || v_script_traffic_source || ''',
                ''' || v_script_traffic_medium || ''',
                ''' || v_script_traffic_name || ''',
                ''' || v_script_last_click_source || ''',
                ''' || v_script_last_click_medium || ''',
                ''' || v_script_last_click_name || ''',
                ''' || v_script_session_traffic_source_last_click_tt || ''',
                ''' || v_script_publisher || ''',
                ''' || v_script_batch_event_index || ''',
                ''' || v_script_batch_page_id || ''',
                ''' || v_script_batch_ordering_id || ''',
                a.ga_session_id,
                a.ga_session_number
            FROM   event a
            LEFT JOIN iden_party b  ON a.hash_id = b.hash_id
            LEFT JOIN contact c    ON a.hash_email = c.hash_email  
                 
        ''';
        EXECUTE IMMEDIATE v_script;
    END FOR;
END;

