BEGIN

########## Ejecucion para probar el Stored Procedure  ####################
/*
DECLARE var_project_storage STRING;
DECLARE var_project_sensitive STRING;
DECLARE var_fecha DATE;

SET var_project_storage = 'prd-izipay-data-storage-pv';
SET var_project_sensitive = 'prd-izipay-data-sensitive';

SET var_fecha = current_date('America/Lima');
*/

  # Declaracion de Variables
  DECLARE query STRING;
  DECLARE var_fecha_ini DATE;
  DECLARE var_fecha_fin DATE;

  DECLARE var_dataset_master_pii STRING;
  DECLARE var_table_iden_party_data_control STRING;
  DECLARE var_dataset_bi_apa STRING;
  DECLARE var_dataset_bi_apm STRING;
  DECLARE var_dataset_master_financial STRING;
  DECLARE var_dataset_master_placement STRING;
  DECLARE var_dataset_master_party STRING;
  DECLARE var_dataset_raw_dataentry_sunat STRING;
  DECLARE var_dataset_raw_ibk STRING;
  DECLARE var_table_base_final_ex STRING;
  DECLARE var_table_web_scrapping_sunat STRING;

  DECLARE var_table_dv_potencial_cuenta STRING;
  DECLARE var_table_dv_alerta_nuevo_potencial STRING;
  DECLARE var_table_t_abono_ibk STRING;
  DECLARE var_table_m_comercio STRING;
  DECLARE var_table_m_direccion STRING;

  SET var_dataset_master_pii ='master_pii';
  SET var_table_iden_party_data_control ='iden_party_data_control';

  SET var_dataset_bi_apa ='bi_apa';  
  SET var_dataset_bi_apm ='bi_apm';  
  SET var_dataset_master_financial ='master_financial';
  SET var_dataset_master_placement ='master_placement';
  SET var_dataset_master_party ='master_party';
  SET var_dataset_raw_dataentry_sunat ='raw_dataentry_sunat';
  SET var_dataset_raw_ibk ='raw_ibk';
  SET var_table_base_final_ex ='base_final_ex';
  SET var_table_web_scrapping_sunat ='web_scrapping_sunat';

  SET var_table_dv_alerta_nuevo_potencial = 'dv_alerta_nuevo_potencial';
  SET var_table_dv_potencial_cuenta = 'dv_potencial_cuenta';
  SET var_table_t_abono_ibk = 't_abono_ibk';
  SET var_table_m_comercio = 'm_comercio';
  SET var_table_m_direccion = 'm_direccion';

  SET var_fecha_ini = date_sub(var_fecha,interval 30 day);
  SET var_fecha_fin = var_fecha;
  

SET query = """
delete from `"""||var_project_storage||"""."""||var_dataset_bi_apa||"""."""||var_table_dv_alerta_nuevo_potencial||"""`
where process_date = '"""||var_fecha||"""' 
""";
EXECUTE IMMEDIATE(query);

SET query = """
  insert into `"""||var_project_storage||"""."""||var_dataset_bi_apa||"""."""||var_table_dv_alerta_nuevo_potencial||"""` 
  (
    process_date,
    itc_company_id,
    itc_company_name,
    party_id_izi,
    segmento_ibk,
    segmento_izipay,
    emp_fac,
    fecha_abono,
    monto_abono_soles,
    monto_abono_dolares,
    departamento,
    provincia,
    distrito,
    direccion,
    telefono_fijo,
    telefono_movil,
    correo_electronico,
    cod_giro_comercio,
    nom_giro_comercio,
    tipo_producto,
    dq_flag_ind,
    dq_control_msg,
    dq_config_id,
    hk_diff,
    start_date,
    end_date,
    flag_active,
    record_source,
    load_date,
    creation_user
  )
  with alerta_ant as 
  (
    select party_id_izi,
    from `"""||var_project_storage||"""."""||var_dataset_bi_apa||"""."""||var_table_dv_alerta_nuevo_potencial||"""`
    group by all 
  ), alerta_nuevo as 
  (
    select a.party_id_izi
    from `"""||var_project_storage||"""."""||var_dataset_master_financial||"""."""||var_table_t_abono_ibk||"""` a
    left join `"""||var_project_storage||"""."""||var_dataset_master_party||"""."""||var_table_m_comercio||"""` c on (a.party_id_izi = c.party_id_izi and c.flag_parque = TRUE)
    where 
      a.process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
      and c.party_id_izi is null 
    group by all 
  ), datos_unicos as
  (
    select nroruc, mcc, giro, tipoproducto
    from `"""||var_project_storage||"""."""||var_dataset_bi_apm||"""."""||var_table_dv_potencial_cuenta||"""`
    qualify row_number() over (partition by nroruc order by importe_data_ibk desc) = 1
  ), datos_ruc as
  (
    select b.party_id_izi, a.nroruc, a.mcc, a.giro, a.tipoproducto
      from datos_unicos a
    inner join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_iden_party_data_control||"""` b on a.nroruc = b.document_number
  ), contacto as 
  (
    select 
      party_id_izi, 
      desemail, 
      numtelefono,
      process_date
    from `"""||var_project_storage||"""."""||var_dataset_raw_ibk||"""."""||var_table_base_final_ex||"""`
    group by all
    qualify row_number() over (partition by party_id_izi order by process_date desc) = 1

  )
  select
    date('"""||var_fecha||"""') as process_date,
    '086' as itc_compay_id,
    'IZIPAY' as itc_company_name,
    a.party_id_izi,
    segmento_ibk,
    segmento_izipay,
    empresa as emp_fac,
    a.process_date as fecha_abono,
    sum(total_abonos_soles) as monto_abono_soles,
    sum(total_abonos_dolares) as monto_abono_dolares,
    departamento,
    provincia,
    distrito,
    e.domicilio_fiscal as direccion,
    cast(null as bytes) as telefono_fijo,
    f.numtelefono as telefono_movil,
    f.desemail as correo_electronico,
    x.mcc as cod_giro_comercio,
    x.giro as nom_giro_comercio,
    x.tipoproducto as tipo_producto,
    true as dq_flag_ind,
    '' as dq_control_msg,
    '' as dq_config_id,
    sha256(upper(cast(a.party_id_izi as string))) as hk_diff,
    cast('2025-07-01' as timestamp) as start_date,
    cast(cast('2099-12-31' as date) as timestamp) as end_date,
    true as flag_active,
    'dv_alerta_nuevo_potencial'  as record_source,
    cast(current_datetime('America/Lima') as timestamp) as load_date,
    session_user() as creation_user
  from `"""||var_project_storage||"""."""||var_dataset_master_financial||"""."""||var_table_t_abono_ibk||"""` a
  join alerta_nuevo c on (a.party_id_izi = c.party_id_izi)
  left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_iden_party_data_control||"""` d on (a.party_id_izi = d.party_id_izi)
  join `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_sunat||"""."""||var_table_web_scrapping_sunat||"""` e on (a.party_id_izi = e.party_id_izi)
  left join contacto f on (a.party_id_izi = f.party_id_izi)
  left join datos_ruc x on (x.party_id_izi = a.party_id_izi)
  left join alerta_ant b on (a.party_id_izi = b.party_id_izi)
  where 
    a.process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
    and b.party_id_izi is null
  group by all
""";
EXECUTE IMMEDIATE(query);

END

