  DECLARE var_dataset_master_pii STRING;
  DECLARE var_table_iden_party_data_control STRING;

  SET var_dataset_bi_riesgo ='bi_riesgo';  
  SET var_dataset_master_risk ='master_risk';
  SET var_dataset_master_party ='master_party';
  SET var_table_dv_coincidencia_documento = 'dv_coincidencia_documento' ;
  SET var_table_m_excluido_blacklist = 'm_excluido_blacklist';
  SET var_table_m_comercio = 'm_comercio';
  SET var_table_dv_coincidencia_bl = 'dv_coincidencia_bl';

  SET var_dataset_master_pii = 'master_pii';
  SET var_table_iden_party_data_control = 'iden_party_data_control'; 




SET query = """
delete from `"""||var_project_storage||"""."""||var_dataset_bi_riesgo||"""."""||var_table_dv_coincidencia_documento||"""`
where process_date = '"""||var_fecha||"""'
""";
EXECUTE IMMEDIATE(query);

SET query = """
  insert into `"""||var_project_storage||"""."""||var_dataset_bi_riesgo||"""."""||var_table_dv_coincidencia_documento||"""` 
  (
    process_date,
    cod_comercio,
    correo_representante_legal,
    cod_bloqueo_comercio,
    detalle_bloqueo_comercio,
    fecha_apertura_comercio,
    cod_situacion_comercio,
    party_id_izi,
    party_id_izi_representante,
    nom_representante_legal,
    segmento_parque,
    nom_comercio,
    num_cuenta_comercio,
    telefono_comercio,
    nom_producto,
    razon_social_dealer,
    record_source,
    load_date,
    creation_user
  )
  select distinct
    date('"""||var_fecha||"""') as process_date,
    b.cod_comercio,
    b.correo_representante_legal,
    b.cod_bloqueo_comercio,
    b.detalle_bloqueo_comercio,
    b.fecha_apertura_comercio,
    b.cod_situacion_comercio,
    b.party_id_izi,
    b.party_id_izi_representante,
    b.nom_representante_legal,
    b.segmento_parque,
    b.nom_comercio,
    b.num_cuenta_comercio,
    b.telefono_comercio,
    b.nom_producto,
    trim(b.razon_social_dealer) as razon_social_dealer,
    'M_COMERCIO, COMERCIOS BLOQUEADOS' as record_source,
    current_datetime("America/Lima") as load_date,
    session_user() as creation_user,
  from `"""||var_project_storage||"""."""||var_dataset_bi_riesgo||"""."""||var_table_dv_coincidencia_bl||"""` a
  left join `"""||var_project_storage||"""."""||var_dataset_master_party||"""."""||var_table_m_comercio||"""` b on (a.party_id_izi = b.party_id_izi or a.party_id_izi_representante = b.party_id_izi_representante)
  left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_iden_party_data_control||"""` c on (b.party_id_izi = c.party_id_izi)
  left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_iden_party_data_control||"""` d on (b.party_id_izi_representante = d.party_id_izi)
  left join `"""||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_m_excluido_blacklist||"""` e on (a.cod_comercio = e.cod_comercio)
  where 
    b.fecha_apertura_comercio >= '2023-01-01' 
    and b.compania = 'IZIPAY' 
    and b.nom_producto <> 'CAJERO CORRESPONSAL' 
    and b.flag_izipay_ya is false 
    and b.segmento_parque in ('BPE','RETAIL') 
    and b.cod_situacion_comercio not in ('3','9') 
    and b.cod_comercio is not null 
    and c.document_number not in ('20603235780','20610313711','20604420157','20605474081') 
    and d.document_number not in ('00000000001','','26955241') 
    and left(b.party_id_izi_representante,1) <> '-'
    and e.cod_comercio is null
    and a.process_date = date('"""||var_fecha||"""')
""";
EXECUTE IMMEDIATE(query);

END

