definicion_sql:
BEGIN

########## Ejecucion para probar el Stored Procedure  ####################
/*
DECLARE var_project_storage STRING;
DECLARE var_fecha DATE;

SET var_project_storage = 'prd-izipay-data-storage-pv';

SET var_fecha = current_date('America/Lima')-1;
*/

  # Declaracion de Variables
  DECLARE query STRING;
  DECLARE var_fecha_fin date;
  DECLARE var_fecha_ini date;


  DECLARE var_dataset_bi_riesgo STRING;
  DECLARE var_dataset_master_risk STRING;
  DECLARE var_table_dv_facturacion_cybersource_trr STRING;
  DECLARE var_table_t_cybersource_trr STRING;

  SET var_dataset_bi_riesgo ='bi_riesgo';  
  SET var_dataset_master_risk ='master_risk';
  SET var_table_dv_facturacion_cybersource_trr = 'dv_facturacion_cybersource_trr' ;
  SET var_table_t_cybersource_trr = 't_cybersource_trr';

  SET var_fecha_ini = date_trunc(date(var_fecha),month);
  SET var_fecha_fin = last_day(date(var_fecha),month);



SET query = """
delete from `"""||var_project_storage||"""."""||var_dataset_bi_riesgo||"""."""||var_table_dv_facturacion_cybersource_trr||"""`
where process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
""";
EXECUTE IMMEDIATE(query);

SET query = """
  insert into `"""||var_project_storage||"""."""||var_dataset_bi_riesgo||"""."""||var_table_dv_facturacion_cybersource_trr||"""` 
  (
    process_date,
    cod_comerciante,
    tipo_servicio,
    cant_trx,
    record_source,
    load_date,
    creation_user
  )
  select 
    date('"""||var_fecha||"""') as process_date,
    cod_comerciante as cod_comerciante,
    case
      when upper(nom_aplicacion) in 
        (
          'ICS_DECISION,ICS_DECISION_EARLY,ICS_SCORE',
          'ICS_DECISION,ICS_SCORE,ICS_DECISION_EARLY',
          'ICS_DECISION_EARLY,ICS_DECISION,ICS_SCORE',
          'ICS_DECISION_EARLY,ICS_SCORE,ICS_DECISION',
          'ICS_SCORE,ICS_DECISION,ICS_DECISION_EARLY',
          'ICS_SCORE,ICS_DECISION_EARLY,ICS_DECISION'
        ) THEN 'DECISION MANAGER' 
      else 'ADVANCED FRAUD SCREEN' end tipo_servicio,
    count(cod_solicitud) as cant_trx,
    't_cybersource_trr' as record_source,
    cast(current_datetime('America/Lima') as timestamp) as load_date,
    session_user() as creation_user
  from `"""||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_t_cybersource_trr||"""` 
  where 
    process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
    and upper(nom_aplicacion) not in ('ICS_CM_ACTION','ICS_IFS_UPDATE')
  group by all
""";
EXECUTE IMMEDIATE(query);

END

