    left join `"""||var_project_storage||"""."""||var_dataset_raw_salesforce||"""."""||var_table_izi_fichaalerta__c||"""` d on (a.izi_fichaalerta__c = d.id)
    where 
      a.recordtypeid = '012VN000000phkVYAQ' and 
      a.izi_estadoeventoretail__c = 'Completado' and 
