BEGIN
  
  DECLARE query STRING;
  DECLARE cant INT64;

  /*
  DECLARE var_project_storage STRING;
  DECLARE var_fecha_ini DATE;
  DECLARE var_fecha_fin DATE;
  SET var_project_storage = 'prd-izipay-data-storage-pv';
  SET var_fecha_ini = current_date('America/Lima')-1;
  SET var_fecha_fin = current_date('America/Lima')-1;

  */
  DECLARE var_dataset_bi_comercial STRING;
  DECLARE var_table_dv_cuenta_sueldo_bcp STRING;
  DECLARE var_dataset_master_placement STRING;
  DECLARE var_table_m_terminales_redpos STRING;
  DECLARE var_dataset_raw_mccenter_adq STRING;
  DECLARE var_table_tptransaction_log STRING;

  SET var_dataset_bi_comercial = 'bi_comercial';
  SET var_table_dv_cuenta_sueldo_bcp = 'dv_cuenta_sueldo_bcp';
  SET var_dataset_master_placement = 'master_placement';
  SET var_table_m_terminales_redpos = 'm_terminales_redpos';
  SET var_dataset_raw_mccenter_adq = 'raw_mccenter_adq';
  SET var_table_tptransaction_log = 'tptransaction_log';
  
## LIMPIAR LA DATA

  SET query = """
  delete from `"""||var_project_storage||"""."""||var_dataset_bi_comercial||"""."""||var_table_dv_cuenta_sueldo_bcp||"""` 
  where 
    process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
  """;
  EXECUTE IMMEDIATE(query);
  
  SET query = """
  insert into `"""||var_project_storage||"""."""||var_dataset_bi_comercial||"""."""||var_table_dv_cuenta_sueldo_bcp||"""` 
  with cte as 
  (
    /*select 
      left(comercio,7) as codigo,
      ruc,
      aplicacion
    from `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_terminales_redpos||"""`
    where
      adq_c_cor ='ADQ-PMP' and 
      aplicacion ='CTASUELDO'
    group by all
*/
    select 
      left(cod_comercio,7) as codigo,
      party_id_izi as ruc,
      case 
        when tipo_aplicacion = 'CTASUELDO' then 'CuentaSueldoBCP'
        when tipo_aplicacion = 'CTASUELDOIBK' then 'CuentaSueldoIBK'
        end as aplicacion
    from `"""||var_project_storage||""".master_product.m_terminal`
    where   
      adq_cajero_corr = 'ADQ-PMP' and
      tipo_aplicacion in ('CTASUELDO','CTASUELDOIBK') and
      party_id_izi is  not null
    group by all
  ) 
  select 
    a.process_date,
    b.ruc,
    left(a.ctxmerchantid,7) as codigo_de_comercio, 
    case left(a.ctxtype, 2)
      when '01' THEN 'Consulta'
      when '02' THEN 'Canje'
      when '03' THEN 'Anulacion'
      when '91' THEN 'Reporte total'
      when '92' THEN 'Reporte detallado'
      else 'Cierre' end as tipo_de_trx,
    a.process_date as fecha_de_operacion, 
    cast(a.ntxamount as float64) as monto_total,
    cast(a.ntxorigamount as float64) as monto_pagado, 
    a.ntxautorization as ID_transaccion,
    a.ntxrrn as id_transaccion_ref,
    a.ctxmessagehost as mensaje, 
    a.ntxcardnumber as tarjeta,
    b.aplicacion as record_source,
    cast(current_datetime('America/Lima') as timestamp) as load_date,
    session_user() as creation_user,
    a.ctxaplicacion as ctxaplicacion
  from `"""||var_project_storage||"""."""||var_dataset_raw_mccenter_adq||"""."""||var_table_tptransaction_log||"""` a 
  inner join cte b on (left(a.ctxmerchantid,7) = b.codigo)
  where 
    a.process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""' and
    left(a.ctxtype, 2) in ('01','02','03','91','92') and
    a.ctxaplicacion in ('CTASUELDO','POS')
  """;
  EXECUTE IMMEDIATE(query);


END

