    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm021||"""` kk on aa.mecest = kk.mecest 
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv068||"""` pp on aa.mecest = pp.mtcest and mtemis='9'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv1001||"""` qq on aa.mecafr = qq.pfcafr
    left join `"""||var_project_operation||"""."""||var_dataset_operation_master_stage||"""."""||var_table_mcfv002||"""` ii on aa.mecest = ii.mecest
    left join `"""||var_project_operation||"""."""||var_dataset_operation_master_stage||"""."""||var_table_mcfm020||"""` jj on aa.mecest = jj.mecest
    left join `"""||var_project_operation||"""."""||var_dataset_operation_master_stage||"""."""||var_table_mcfm024||"""` mm on aa.mecest = mm.cod
