      l.ccmai1 as mailggen,
      m.ccnomb as cont_fac_elec,
      n.ccdire as cont8_fac_elec,
      m.ccmai1 as mail_fact_elec,
      q.ccmail as email_rep_proc,
      o.ccmai1 as email_opera,
      k.ccdocu as dni,
      p.cccpos as tdoc_ex,
      case when p.ccrefe is not null then p.ccrefe else '' end as pais_ex,
      case when p.ccdocu is not null then p.ccdocu else '' end as nrodoc_ex  
    from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm019i||"""` a
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` j on a.mecest =j.cccest and j.cccate='3'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` k on a.mecest =k.cccest and k.cccate='1'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` l on a.mecest =l.cccest and l.cccate='2'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` m on a.mecest =m.cccest and m.cccate='7'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` n on a.mecest =n.cccest and n.cccate='8'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` q on a.mecest =q.cccest and q.cccate='6'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""o` o on a.mecest =o.cccest and o.cccate='5'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` p on a.mecest =p.cccest and p.cccate='8' and p.cccpos ='0';
  """;
  EXECUTE IMMEDIATE(query);

  ------------------------------------logica #4-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_operation||"""."""||var_dataset_operation_master_stage||"""."""||var_table_mcfm024||"""` as
    select 
      distinct a.mecest as cod, 
      j.m4qtty as term_dial,
      k.m4qtty as term_cel_fij,
