  ------------------------------------logica #11-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_operation||"""."""||var_dataset_operation_master_stage||"""."""||var_table_mcfm015||"""` as
    with cte7 as (
      select
        m.mecest,
        a.nroruc,
        ifnull(b0.rursoc, b1.rursoc) as rursoc, /*is null(b0.rursoc, b1.rursoc) as rursoc,*/
        ifnull(b0.rutdoi, cast(case length(a.nroruc) when 11 then 6 when 8 then 1 else 4 end as string)) as rutdoi, /*is null(b0.rutdoi, case len(a.nroruc) when 11 then 6 when 8 then 1 else 4 end) as rutdoi,*/
        b1.ructes
      from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm019i||"""` m
      left join `"""||var_project_operation||"""."""||var_dataset_operation_master_stage||"""."""||var_table_mcfv030||"""` a on m.mecest = a.cod
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm015||"""` b0 on a.nroruc = b0.ruruce
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm015||"""` b1 on m.meruce = b1.ruruce
      )
    select distinct
      cc.mecest,
      cc.nroruc,
      cc.rursoc,
      cc.rutdoi as tipo_de_documento,
      cc.ructes as cta_esp,
      case
          when instr(b2.pgdesc, ' L') > 7 then substr(b2.pgdesc, 1, instr(b2.pgdesc, ' L') - 7)
          else ''
      end as descripcion
      -- left(b2.pgdesc,strpos(' l',b2.pgdesc)-7) as descripcion /*left(b2.pgdesc,charindex(' l',b2.pgdesc)-7) as [descripcion]*/
    from cte7 cc
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b2 on cc.rutdoi=b2.pgcodi and b2.pgtipo = cc.rutdoi;
  """;
  EXECUTE IMMEDIATE(query);

