  SET query = """
      create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv075||"""` as
        select 
            distinct a.cod as cod,
            b0.pgdesc as `ent_caj_corr`,
            b2.pgdesc as `dealer`,
            b3.pgdesc as `dealer_eje`,
            b4.pgdesc as `faci_serv`,
            b5.pgdesc as `faci_pagos`,
            b6.pgdesc as `tip_com`, 
            b7.pgdesc as `tip_prue`,
            b1.meptco as `ptocomp`,
            b1.meppoi as `ptoppoint`,
            b1.mecsue as `ptocsueldo`,
            b1.meuqps as `qps`,
            left (b1.memraf, 2) as `coddealer`,
            b1.memraf as `codeje`,
            medvry as `delivery`,
            meavmn as `vou_manual`, 
            b1.meamct as `mant_cta`,
            b1.meendc as `envio_dua`,
            b1.meprly as `prod_lyra`, 
            b1.medumy as `dummy`,

            --la marcar de microcomercios se da en la tabla mcft027
            --para visa en el campo memime = d
            --para mastercard en el campo mefil1 = y
            b1.`memime` as `f_mime_va`,
            b1.`mefil1` as `f_mime_mc`,

            b1.mefivi as `izi_virtual`,
            b1.meceli as `izi_celular`,
            --b1.medeud as `pdd`,
            b1.meptrp as `ptorp`,
            case when d1.mccest is not null then
              case when c.pgdesc = '' then d1.mctipo else c.pgdesc end
            else null end as `grupo_amex`
          /*into #mcfv075*/
      from `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv030||"""` a -- instead of mcfm019i to have correct nroruc.
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm027||"""` b1 on a.cod = b1.mecest 
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b0 on b1.meencc=b0.pgcodi and pgtipo = 'IAENCC' 
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b2 on left(b1.memraf,2)=b2.pgcodi and b2.pgtipo = 'dealer' 
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b3 on b1.memraf=b3.pgcodi and b3.pgtipo = 'IAMRAF'
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b4 on b1.mefsrv=b4.pgcodi and b4.pgtipo = 'IAFSRV'
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b5 on b1.mefpag=b5.pgcodi and b5.pgtipo = 'IAFPAG'
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b6 on b1.mecond=b6.pgcodi and b6.pgtipo = 'IACOND'
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b7 on b1.metppr=b7.pgcodi and b7.pgtipo = 'IATPPR'
      left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_cte01||"""` d1 on a.cod=d1.mccest
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` c on rtrim(d1.mctipo)= rtrim(c.pgcodi) and c.pgtipo = 'MARCA';
  """;
  EXECUTE IMMEDIATE(query);

  -- ------------------------------------logica #6-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcft168||"""` as

        with cte2 as (
            select
                distinct 
                mecest, 
                lpad(rtrim(megrue), 6, '0') as megrue,
                lpad(rtrim(mececo), 6, '0') as mececo,
                mecafr
            from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||""".."""||var_table_mcfm019i||"""`
        ),
        cte3 as (
            select 
                distinct 
                mecest as cod,
                b.tbdeslar as grup_econo_desc,
                row_number() over (partition by mecest order by tbcodtbl, tbcodigo, tbdeslar) as num
            from cte2 as a
            left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcft168||"""` b 
                on a.megrue = b.tbcodigo and b.tbcodtbl = 'grupoe'
            where 
                not (b.tbcodtbl = 'grupoe' and cast(b.tbcodigo as string) = '71' and b.tbdeslar = 'korea motors') 
                and not (b.tbcodtbl = 'grupoe' and cast(b.tbcodigo as string) = '72' and b.tbdeslar = 'body secret')
        )
        
        select 
            distinct 
            a.mecest as cod, 
            b.grup_econo_desc, 
            b1.tbdeslar as grup_franq_desc,
            b2.tbdeslar as centro_com_desc
        from cte2 as a
        left join cte3 as b 
            on a.mecest = b.cod and b.num = 1
        left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcft168||"""` b1 
            on a.mecafr = b1.tbcodigo and b1.tbcodtbl = 'franqu'
        left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcft168||"""` b2 
            on a.mececo = b2.tbcodigo and b2.tbcodtbl = 'cencom';
    """;
    EXECUTE IMMEDIATE(query);

  ------------------------------------logica #7-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_izfs017||"""` as
