      case when oo.f_mime_mc = 'y' then '422990' else '-' end as flg_micro_mc,
      trim(nullif(aa.meuser,'')) as usuario,
      trim(nullif(aa.mepagw,'')) as pag_web,
      trim(nullif(aa.meteof,'0')) as tel_ofi,
      trim(nullif(aa.mefxof,'0')) as fax_ofi,
      trim(nullif(aa.medatd,'')) as dia_aten_d,
      trim(nullif(aa.medath,'')) as dia_aten_h,
      trim(nullif(aa.mehatd,'0')) as hor_aten_d,
      trim(nullif(aa.mehath,'0')) as hor_aten_h,
      trim(nullif(aa.mecuad,'')) as cuadrante,
       oo.izi_virtual,
      case when oo.izi_celular = '0' then '-' else oo.izi_celular end as izi_celular,
      rr.tipo_de_documento,
      rtrim(ltrim(nullif(rr.descripcion,''))) as descripcion,
      case when strpos ('@',jj.email_opera)>1 then trim(jj.email_opera) else '-' end as email_opera,
      case when strpos ('@',email_rep_proc)>1 then trim(email_rep_proc) else '-' end as email_rep_proc,
      case when cast(iz.crstat as int64) = 1 then 'y' end as marca_cima,
      jj.tdoc_ex,
      jj.pais_ex,
      jj.nrodoc_ex,
      case when trim (ar.medeud) = '' then '-' else trim (ar.medeud) end as flg_pago_deuda,
 
      case when ar.mefil6 = 'ARISAL' then 'ARISALE' else '-' end as flg_arisale,
      case when ar.mefil6 = 'ARISAL' then ar.mefil8 else null end as fec_arisale,
      --case when ar.mefil6 = 'arisal' then cast(ar.mefil8 as date) else null end as fec_arisale,

      case when ar.mefil3 = 'Y' and cast(tr.pgsitu as string) = '1' then ifnull(trim(ar.mefil3), '-') else '-' end as flg_pptr,

      case when ar.mefil3 = 'Y' and tr.pgsitu = '1' then trim(tr.pgfing) else '-' end as fec_pptr,
      ifnull (trim (iy.metapp), '-') as flg_izi_ya,

      case when aa.mecest = b.cod_comercio then '1' else '-' end as flg_no_domiciliado,
      """||var_periodo||""" as periodo,
      cast(datetime_sub(current_datetime(), interval 5 hour) as date) as fechaproceso,

      cast(true as string) dq_flag_ind,
      '' as dq_control_msg,
      '' as dq_config_id,
      sha256(upper(cast(aa.mecest as string))) as hk_diff,
      cast(current_datetime ('America/Lima') as timestamp) as start_date,
      cast(current_datetime ('America/Lima') as timestamp) as end_date,
      true as flag_active,
      'as400_mcestab' as record_source,
      cast(current_datetime('America/Lima') as timestamp) as load_date,
      session_user() as creation_user
    from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm019i||"""` aa
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfs922||"""` bb on aa.mecest = bb.mccodcom
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv030||"""` dd on aa.mecest = dd.cod
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv012||"""` ee on aa.memcc = ee.mcc012
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv014||"""` ff on aa.mesucu = ff.t14cod
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm602||"""` gg on aa.meejec = gg.codigb 
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm602||"""` g1 on aa.meprom = g1.codigb
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv004||"""` hh on aa.mebcop = hh.bacodi
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm021||"""` kk on aa.mecest = kk.mecest 
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv068||"""` pp on aa.mecest = pp.mtcest and mtemis='9'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv1001||"""` qq on aa.mecafr = qq.pfcafr
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv002||"""` ii on aa.mecest = ii.mecest
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm020||"""` jj on aa.mecest = jj.mecest
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm024||"""` mm on aa.mecest = mm.cod
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcft168||"""` nn on aa.mecest = nn.cod
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv075||"""` oo on aa.mecest = oo.cod 
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_izfs017||"""` iz on dd.nroruc = iz.crndoc 
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv0752||"""` ppo on iz.crcemp = ppo.pgdesc1 and iz.crtcob = ppo.pgdesc2 
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_swfv100com||"""` sw on sw.cmcom = aa.mecest
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm015||"""` rt on iz.crtdoc = rt.rutdoi and iz.crndoc = rt.ruruce
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm027||"""` ar on aa.mecest = ar.mecest
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfs114||"""` tr on aa.mecest = tr.pgcest
    -- tr9656 2024/01/08 | add mcfm029 to get metapp flag 'tk' (izipayya).
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm029||"""` iy on aa.mecest = iy.mecest
    -- tr9656 2024/01/08 | join with a processed mcfm015 to get tipo_doc.
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm015||"""` rr on aa.mecest = rr.mecest
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_de_finanzas||"""."""||var_table_com_no_domiciliado||"""` b on aa.mecest = b.cod_comercio;

     --2024/01/08 | 3,017,803
    --07:04 segundos
    
  """;
  EXECUTE IMMEDIATE(query);

  -- /* inserta data a la tabla historica m_establecimiento_hist*/
  -- IF var_process_date = last_day(var_process_date)
  --  THEN

  --   /* Eliminar registros del mismo periodo en la tabla destino antes de insertar los nuevos datos*/
  --   SET query = """
  --     delete from `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_establecimiento_hist||"""` 
  --     --where process_date in ("""||var_process_date||""" from `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_establecimiento||"""`  )
  --     where process_date = '"""||var_process_date||"""';
  --   """;
  --   EXECUTE IMMEDIATE(query);

  --   /* Inserta registros del mismo periodo en la tabla destino antes de insertar los nuevos datos*/
  --   SET query = """
  --     insert into `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_establecimiento_hist||"""`
  --     select *
  --     from `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_establecimiento||"""`
  --   """;
  --   EXECUTE IMMEDIATE(query);
  -- END IF;


END

