CREATE PROCEDURE `prd-izipay-data-operation`.master_stage_placement.prc_load_master_m_establecimiento(var_project_operation STRING, var_project_storage STRING, var_dataset_master_stage_placement STRING, var_dataset_master_placement STRING, var_dataset_storage_raw_as400 STRING, var_dataset_storage_raw_de_finanzas STRING, var_table_m_establecimiento STRING, var_table_cte01 STRING, var_table_izfs017 STRING, var_table_mcfm004 STRING, var_table_mcfm015 STRING, var_table_mcfm019i STRING, var_table_mcfm020 STRING, var_table_mcfm020o STRING, var_table_mcfm021 STRING, var_table_mcfm024 STRING, var_table_mcfm027 STRING, var_table_mcfm029 STRING, var_table_mcfm602 STRING, var_table_mcfs114 STRING, var_table_mcfs922 STRING, var_table_mcft124 STRING, var_table_mcft168 STRING, var_table_mcfv002 STRING, var_table_mcfv004 STRING, var_table_mcfv012 STRING, var_table_mcfv014 STRING, var_table_mcfv030 STRING, var_table_mcfv068 STRING, var_table_mcfv075 STRING, var_table_mcfv0752 STRING, var_table_mcfv1001 STRING, var_table_swfv100com STRING, var_table_com_no_domiciliado STRING)
BEGIN
  --=== declaracion de variables generales ============
  declare query STRING;
  declare var_periodo int64;
  declare var_table_m_establecimiento_hist string;
  declare var_process_date date default current_date('America/Lima')-1;

  --======= set de variables generales ==================
 /*
  declare var_project_operation STRING;
  declare var_project_storage STRING;
  declare var_dataset_master_stage_placement STRING;
  declare var_dataset_master_placement STRING;
  declare var_dataset_storage_raw_as400 STRING;
  declare var_dataset_storage_raw_de_finanzas string;
  declare var_table_m_establecimiento string;
  declare periodo string;
  declare var_table_cte01 string;
  declare var_table_izfs017 string;
  declare var_table_mcfm004 string;
  declare var_table_mcfm015 string;
  declare var_table_mcfm019i string;
  declare var_table_mcfm020 string;
  declare var_table_mcfm020o string;
  declare var_table_mcfm021 string;
  declare var_table_mcfm024 string;
  declare var_table_mcfm027 string;
  declare var_table_mcfm029 string;
  declare var_table_mcfm602 string;
  declare var_table_mcfs114 string;
  declare var_table_mcfs922 string;
  declare var_table_mcft124 string;
  declare var_table_mcft168 string;
  declare var_table_mcfv002 string;
  declare var_table_mcfv004 string;
  declare var_table_mcfv012 string;
  declare var_table_mcfv014 string;
  declare var_table_mcfv030 string;
  declare var_table_mcfv068 string;
  declare var_table_mcfv075 string;
  declare var_table_mcfv0752 string;
  declare var_table_mcfv1001 string;
  declare var_table_swfv100com string;
  declare var_table_com_no_domiciliado string;

  set var_project_operation = 'dev-izipay-data-operation';
  set var_project_storage = 'dev-izipay-data-storage';
  set var_dataset_master_stage_placement = 'master_stage_placement';
  set var_dataset_master_placement = 'master_placement';
  set var_dataset_storage_raw_as400 = 'raw_as400';
  set var_dataset_storage_raw_de_finanzas = 'raw_de_finanzas';  
  set var_table_m_establecimiento = 'm_establecimiento';
  set var_table_cte01 = 'cte01';
  set var_table_izfs017 = 'izfs017';
  set var_table_mcfm004 = 'mcfm004';
  set var_table_mcfm015 = 'mcfm015';
  set var_table_mcfm019i = 'mcfm019i';
  set var_table_mcfm020 = 'mcfm020';
  set var_table_mcfm020o = 'mcfm020o';
  set var_table_mcfm021 = 'mcfm021';
  set var_table_mcfm024 = 'mcfm024';
  set var_table_mcfm027 = 'mcfm027';
  set var_table_mcfm029 = 'mcfm029';
  set var_table_mcfm602 = 'mcfm602';
  set var_table_mcfs114 = 'mcfs114';
  set var_table_mcfs922 = 'mcfs922';
  set var_table_mcft124 = 'mcft124';
  set var_table_mcft168 = 'mcft168';
  set var_table_mcfv002 = 'mcfv002';
  set var_table_mcfv004 = 'mcfv004';
  set var_table_mcfv012 = 'mcfv012';
  set var_table_mcfv014 = 'mcfv014';
  set var_table_mcfv030 = 'mcfv030';
  set var_table_mcfv068 = 'mcfv068';
  set var_table_mcfv075 = 'mcfv075';
  set var_table_mcfv0752 = 'mcfv0752';
  set var_table_mcfv1001 = 'mcfv1001';
  set var_table_swfv100com = 'swfv100com';
  set var_table_com_no_domiciliado = 'com_no_domiciliado';
*/

  --===============================================
    -- set var_table_tmp_izfs017 = concat('tmp_',m_establecimiento);
    SET var_table_m_establecimiento_hist = concat(var_table_m_establecimiento,'_hist');
    -- set var_process_date = current_date('America/Lima') - 1;

    /*Obtener data para la variable "va_periodo"*/
    SET query = """
      select
        max(cast(substring(mefape,0,6) as int64))
        from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm019i||"""`
    """;
    EXECUTE IMMEDIATE(query)
    into var_periodo;

    -- /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
    -- IF ifnull(cant,0) > 0 

    --   THEN

    --     /* Crear tablas temporales con los datos sumando las columnas adicionales para auditoria*/
    --     SET query = """
    --       create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_tmp_izfs017||"""` as
    --       select
    --         cast(crcemp as string) as crcemp,
  --============================================================================================
  /*==================================proceso 3=========================================== 
  construccion de tablas temporales con las logicas para cada proceso
  =======================================================================================*/

  /* Crear tablas temporales*/
 
  ------------------------------------logica #1-------------------------------------------
   SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv030||"""` as
    select 
      distinct mecest as cod,
      g.mctcom,
      case when c.rursoc is null then a.mersoc else c.rursoc end razsoc,
      case when ltrim(rtrim(b.mcnomfp))='vendemas' then b.mcruc else a.meruce end nroruc,
      /*case when g2.mcecmr!='0' then substring(cast(g.mcecmr as varchar(10)),1,5) else null end cmrcnv,*/
      case when g2.mcecmr != '0' then substr(cast(g.mcecmr as string), 1, 5) else null end as cmrcnv,
      case when g2.mcecmr!='0' then right(g.mcecmr,4) else null end cmrloc,
      case when g1.mccesd=mecest then 'mn' else null end mltmon 
    /*into #mcfv030*/
    from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm019i||"""` a
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfs922||"""` b on a.mecest = b.mccodcom
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv030||"""` g on a.mecest = g.mccome and mctcom = 'mpos'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv030||"""` g1 on a.mecest = g1.mccesd 
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv030||"""` g2 on a.mecest = g2.mccome 
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm015||"""` c on a.meruce = c.ruruce;
  """;
  EXECUTE IMMEDIATE(query);

  ------------------------------------logica #2-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv002||"""` as
    with cte as
    (
      select 
        distinct a.mecest,
        i.cepagt as tercer,
        i.cetcta as tipcta,
        i.cectct as nrocta, 
        cetdot as tip_doc_t,
        ceruct as nro_doc_t,
        cenomt as titular_t,ll.mcoterm as multicom,
        row_number() over (partition by cecest order by mcocest,mcoterm desc) as flag
      from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm019i||"""` a
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv002||"""` i on a.mecest = i.cecest and trim(i.ceprod)='' 
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm004||"""` ll on a.mecest = ll.mcocest
    )
    select *
    from cte where flag=1;
  """;
  EXECUTE IMMEDIATE(query);

  ------------------------------------logica #3-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm020||"""` as
    select 
      distinct a.mecest,
      j.ccnomb as contcom,
      j.ccmai1 as mailcom,
      k.ccnomb as reprleg,
      k.ccmai1 as mailrleg,
      l.ccnomb as gtegral,
      l.ccmai1 as mailggen,
      m.ccnomb as cont_fac_elec,
      n.ccdire as cont8_fac_elec,
      m.ccmai1 as mail_fact_elec,
      q.ccmail as email_rep_proc,
      o.ccmai1 as email_opera,
      k.ccdocu as dni,
      p.cccpos as tdoc_ex,
      case when p.ccrefe is not null then p.ccrefe else '' end as pais_ex,
      case when p.ccdocu is not null then p.ccdocu else '' end as nrodoc_ex  
    from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm019i||"""` a
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` j on a.mecest =j.cccest and j.cccate='3'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` k on a.mecest =k.cccest and k.cccate='1'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` l on a.mecest =l.cccest and l.cccate='2'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` m on a.mecest =m.cccest and m.cccate='7'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` n on a.mecest =n.cccest and n.cccate='8'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` q on a.mecest =q.cccest and q.cccate='6'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020o||"""` o on a.mecest =o.cccest and o.cccate='5'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm020||"""` p on a.mecest =p.cccest and p.cccate='8' and p.cccpos ='0';
  """;
  EXECUTE IMMEDIATE(query);

  ------------------------------------logica #4-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm024||"""` as
    select 
      distinct a.mecest as cod, 
      j.m4qtty as term_dial,
      k.m4qtty as term_cel_fij,
      l.m4qtty as term_cel_mov,
      m.m4qtty as term_ip,
      n.m4qtty as term_lan,
      z.m4qtty as term_cip,
      o.m4qtty as term_cpp
    from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm019i||"""` a
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm024||"""` j on a.mecest =j.m4cest and j.m4tico='1'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm024||"""` k on a.mecest =k.m4cest and k.m4tico='2'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm024||"""` l on a.mecest =l.m4cest and l.m4tico='3'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm024||"""` m on a.mecest =m.m4cest and m.m4tico='4'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm024||"""` n on a.mecest =n.m4cest and n.m4tico='5'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm024||"""` z on a.mecest =z.m4cest and z.m4tico='6'
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm024||"""` o on a.mecest =o.m4cest and o.m4tico='7';
  """;
  EXECUTE IMMEDIATE(query);

 ------------------------------------logica #5-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_cte01||"""` as
    select 
        mccest,
        left(mctipo,2) as mctipo,
        row_number() over (partition by mccest order by mctipo desc) as row2
    from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcft124||"""`
  
  """;
  EXECUTE IMMEDIATE(query);

  SET query = """
    with cte1 as (
      select  
          mccest,
          mctipo 
      from `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_cte01||"""`
      where
          row2=1
      )
      select *
      from cte1
  """;
  EXECUTE IMMEDIATE(query);

  
  SET query = """
      create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv075||"""` as
        select 
            distinct a.cod as cod,
            b0.pgdesc as `ent_caj_corr`,
            b2.pgdesc as `dealer`,
            b3.pgdesc as `dealer_eje`,
            b4.pgdesc as `faci_serv`,
            b5.pgdesc as `faci_pagos`,
            b6.pgdesc as `tip_com`, 
            b7.pgdesc as `tip_prue`,
            b1.meptco as `ptocomp`,
            b1.meppoi as `ptoppoint`,
            b1.mecsue as `ptocsueldo`,
            b1.meuqps as `qps`,
            left (b1.memraf, 2) as `coddealer`,
            b1.memraf as `codeje`,
            medvry as `delivery`,
            meavmn as `vou_manual`, 
            b1.meamct as `mant_cta`,
            b1.meendc as `envio_dua`,
            b1.meprly as `prod_lyra`, 
            b1.medumy as `dummy`,

            --la marcar de microcomercios se da en la tabla mcft027
            --para visa en el campo memime = d
            --para mastercard en el campo mefil1 = y
            b1.`memime` as `f_mime_va`,
            b1.`mefil1` as `f_mime_mc`,

            b1.mefivi as `izi_virtual`,
            b1.meceli as `izi_celular`,
            --b1.medeud as `pdd`,
            b1.meptrp as `ptorp`,
            case when d1.mccest is not null then
              case when c.pgdesc = '' then d1.mctipo else c.pgdesc end
            else null end as `grupo_amex`
          /*into #mcfv075*/
      from `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv030||"""` a -- instead of mcfm019i to have correct nroruc.
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm027||"""` b1 on a.cod = b1.mecest 
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b0 on b1.meencc=b0.pgcodi and pgtipo = 'IAENCC' 
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b2 on left(b1.memraf,2)=b2.pgcodi and b2.pgtipo = 'dealer' 
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b3 on b1.memraf=b3.pgcodi and b3.pgtipo = 'IAMRAF'
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b4 on b1.mefsrv=b4.pgcodi and b4.pgtipo = 'IAFSRV'
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b5 on b1.mefpag=b5.pgcodi and b5.pgtipo = 'IAFPAG'
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b6 on b1.mecond=b6.pgcodi and b6.pgtipo = 'IACOND'
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` b7 on b1.metppr=b7.pgcodi and b7.pgtipo = 'IATPPR'
      left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_cte01||"""` d1 on a.cod=d1.mccest
      left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` c on rtrim(d1.mctipo)= rtrim(c.pgcodi) and c.pgtipo = 'MARCA';
  """;
  EXECUTE IMMEDIATE(query);

  -- ------------------------------------logica #6-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcft168||"""` as

        with cte2 as (
            select
                distinct 
                mecest, 
                lpad(rtrim(megrue), 6, '0') as megrue,
                lpad(rtrim(mececo), 6, '0') as mececo,
                mecafr
            from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||""".."""||var_table_mcfm019i||"""`
        ),
        cte3 as (
            select 
                distinct 
                mecest as cod,
                b.tbdeslar as grup_econo_desc,
                row_number() over (partition by mecest order by tbcodtbl, tbcodigo, tbdeslar) as num
            from cte2 as a
            left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcft168||"""` b 
                on a.megrue = b.tbcodigo and b.tbcodtbl = 'grupoe'
            where 
                not (b.tbcodtbl = 'grupoe' and cast(b.tbcodigo as string) = '71' and b.tbdeslar = 'korea motors') 
                and not (b.tbcodtbl = 'grupoe' and cast(b.tbcodigo as string) = '72' and b.tbdeslar = 'body secret')
        )
        
        select 
            distinct 
            a.mecest as cod, 
            b.grup_econo_desc, 
            b1.tbdeslar as grup_franq_desc,
            b2.tbdeslar as centro_com_desc
        from cte2 as a
        left join cte3 as b 
            on a.mecest = b.cod and b.num = 1
        left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcft168||"""` b1 
            on a.mecafr = b1.tbcodigo and b1.tbcodtbl = 'franqu'
        left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcft168||"""` b2 
            on a.mececo = b2.tbcodigo and b2.tbcodtbl = 'cencom';
    """;
    EXECUTE IMMEDIATE(query);

  ------------------------------------logica #7-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_izfs017||"""` as
    with cte4 as (
      select
        row_number() over (partition by crndoc order by crndoc desc) as flag,
        crndoc,
        crstat,
        lpad(trim(iz.crcemp), 3, '0') as crcemp,
        lpad(trim(iz.crtcob), 3, '0') as crtcob,
        crtdoc
      from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_izfs017||"""` iz
      where cast(iz.crstat as int64) = 1
    )
    select
      crndoc,
      crstat,
      crcemp,
      crtcob,
      crtdoc
    from cte4
    where flag = 1;
  """;
  EXECUTE IMMEDIATE(query);

  ------------------------------------logica #8-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfv0752||"""` as
    select 
      distinct
      left(ppo.pgdesc, 3) as pgdesc1,
      substr(ppo.pgdesc, 4, 3) as pgdesc2, -- right(left(...), ...) can be replaced with substr for clarity
      ppo.pgtipo,
      ppo.pgcodi
    from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfv075||"""` ppo
    where ppo.pgtipo = 'pacizi' and ppo.pgcodi = 'srv001';
  """;
  EXECUTE IMMEDIATE(query);

  ------------------------------------Logica #9-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_swfv100com||"""` as
    select 
      cmcom, 
      max(case when cmbinsu = '54593899' then 1 else 0 end) as flag_swfv100com
    from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_swfv100com||"""`
    group by cmcom;
  """;
  EXECUTE IMMEDIATE(query);

  ------------------------------------logica #9-------------------------------------------
  SET query = """
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfs114||"""` as
    with cte5 as (
      select
        row_number() over (partition by pgcest order by pgfing desc) as flag,
