  ------------------------------------logica #10-------------------------------------------
  SET query = """  
    create or replace table `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm029||"""` as
    with cte6 as (
      select
        row_number() over (partition by mecest order by mefein desc) as flag,
        mecest,
        mefein,
        metapp
      from `"""||var_project_storage||"""."""||var_dataset_storage_raw_as400||"""."""||var_table_mcfm029||"""`)
