    -- tr9656 2024/01/08 | add mcfm029 to get metapp flag 'tk' (izipayya).
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm029||"""` iy on aa.mecest = iy.mecest
    -- tr9656 2024/01/08 | join with a processed mcfm015 to get tipo_doc.
    left join `"""||var_project_storage||"""."""||var_dataset_master_stage_placement||"""."""||var_table_mcfm015||"""` rr on aa.mecest = rr.mecest
    left join `"""||var_project_storage||"""."""||var_dataset_storage_raw_de_finanzas||"""."""||var_table_com_no_domiciliado||"""` b on aa.mecest = b.cod_comercio;

     --2024/01/08 | 3,017,803
    --07:04 segundos
    
  """;
  EXECUTE IMMEDIATE(query);

  -- /* inserta data a la tabla historica m_establecimiento_hist*/
  -- IF var_process_date = last_day(var_process_date)
  --  THEN

  --   /* Eliminar registros del mismo periodo en la tabla destino antes de insertar los nuevos datos*/
