  --     delete from `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_establecimiento_hist||"""` 
  --     --where process_date in ("""||var_process_date||""" from `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_establecimiento||"""`  )
  --     where process_date = '"""||var_process_date||"""';
  --   """;
  --   EXECUTE IMMEDIATE(query);

  --   /* Inserta registros del mismo periodo en la tabla destino antes de insertar los nuevos datos*/
  --   SET query = """
  --     insert into `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_establecimiento_hist||"""`
  --     select *
  --     from `"""||var_project_storage||"""."""||var_dataset_master_placement||"""."""||var_table_m_establecimiento||"""`
