   select count(1)
   from `"""||var_project_storage||"""."""||var_dataset_master_product||"""."""||var_table_t_afiliacion_arisale||"""` 
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  IF ifnull(cant,0) = 0 
    THEN

  EXECUTE IMMEDIATE """ select min(process_date),max(process_date)
    FROM `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_cx||"""."""||var_table_afiliacion_arisale||"""`
    """
    into var_fecha_ini, var_fecha_fin;

  END IF;


  /* Borra data de la tabla destino antes de insertar los nuevos datos*/
  SET query = """
    delete from `"""||var_project_storage||"""."""||var_dataset_master_product||"""."""||var_table_t_afiliacion_arisale||"""` 
    where process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
  """;
  EXECUTE IMMEDIATE(query);

  /* Insertar los datos desde la tabla raw a la tabla destino*/
  SET query = """
    insert into `"""||var_project_storage||"""."""||var_dataset_master_product||"""."""||var_table_t_afiliacion_arisale||"""` 
    (
      process_date
      ,fecha_proceso
      ,codigo
      ,party_id_izi
      ,razon_social
      ,datos_cliente
      ,telefono
      ,tipo_cliente
      ,plan_arisale
      ,tipo_venta
      ,canal
      ,flag_credenciales_enviadas
      ,flag_licencia_activa
      ,record_source
      ,load_date
      ,creation_user
    )
    select
      a.process_date
      ,parse_date('%d/%m/%Y',a.fecha_proceso) as fecha_proceso
      ,a.codigo
      ,a.party_id_izi
      ,a.razon_social
      ,a.datos_cliente
      ,a.telefono
      ,a.tipo_de_cliente
      ,a.plan_ari
      ,a.tipo_venta
      ,a.p_canal
      ,if  (upper(trim(a.credenciales_enviadas)) = 'SI', 1, 0) as flag_credenciales_enviadas 
      ,if (upper(trim(a.licencia_activa)) = 'SI', 1, 0) as flag_licencia_activa
      ,'afiliacion_arisale' as record_source
      ,cast(current_datetime('America/Lima') as timestamp) as load_date
      ,session_user() as creation_user
    from `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_cx||"""."""||var_table_afiliacion_arisale||"""` a
    where process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
    """;
  EXECUTE IMMEDIATE(query);

END

