        when left(trim(b.ntrchipnumber),6) = '895106' then 'MOVISTAR'
        when left(trim(b.ntrchipnumber),6) = '895110' then 'CLARO'
        when left(trim(b.ntrchipnumber),6) = '895117' then 'ENTEL'
