            when trim(a.chip) <> '' THEN 'GPRS FIJO'
            when trim(a.medio_mcc) = 'ETHERNET' THEN 'IP'
            when trim(a.medio_mcc) = 'DIAL' THEN 'DIAL'
            else 'IP'	end
        ) as tipo_conexion,
      upper(trim(a.descripcion_terminal)) as descripcion_terminal,
