BEGIN
  /************************************************************
   * Declaración de variables
   ************************************************************/
  DECLARE query STRING;
  DECLARE cant INT64;

  -- Datasets base
  DECLARE var_dataset_raw_as400 STRING;
  DECLARE var_dataset_master_stage_risk STRING;
  DECLARE var_dataset_raw_dataentry_operaciones STRING;
  DECLARE var_dataset_master_risk STRING;  
  DECLARE var_table_m_ard_as400 STRING;
  DECLARE var_table_rol500_outgoing STRING;
  DECLARE var_table_rol500_incoming STRING;
  DECLARE var_table_mcfs108 STRING;
  DECLARE var_table_mcft107 STRING;
  DECLARE var_table_mcfs005al STRING;
  DECLARE var_table_tmp STRING;  
  DECLARE var_table_mcfv075 STRING;

  /************************************************************
   * asignación de variables
   ************************************************************/
  SET var_dataset_raw_as400 = 'raw_as400';
  SET var_dataset_master_stage_risk = 'master_stage_risk';
  SET var_dataset_raw_dataentry_operaciones = 'raw_dataentry_operaciones';  
  SET var_dataset_master_risk = 'master_risk';
  SET var_table_m_ard_as400 = 'm_ard_as400';
  SET var_table_rol500_outgoing = 'rol500_outgoing';
  SET var_table_rol500_incoming = 'rol500_incoming';
  SET var_table_mcfs108 = 'mcfs108';
  SET var_table_mcft107 = 'mcft107';
  SET var_table_mcfs005al = 'mcfs005al';  
  SET var_table_mcfv075 = 'mcfv075';
  SET var_table_tmp = CONCAT('tmp_', var_table_m_ard_as400);
  
  /*
DECLARE var_project_operation STRING;
DECLARE var_project_storage STRING;
DECLARE var_project_sensitive STRING;

SET var_project_operation = 'prd-izipay-data-operation';
SET var_project_storage = 'prd-izipay-data-storage-pv';
SET var_project_sensitive = 'prd-izipay-data-storage-pv';

CALL `prd-izipay-data-operation.master_stage_risk.prc_load_m_ard_as400`(var_project_operation, var_project_storage, var_project_sensitive);
  */ 
  
  
  /************************************************************
   * Paso 1: Crear tabla temporal
   ************************************************************/
  SET query = """
  create or replace table """||var_project_operation||"""."""||var_dataset_master_stage_risk||"""."""||var_table_tmp||""" as
  with contracargo as (
      select distinct tarjeta_enmascarada,pdaren from 
      (
      select tarjeta_enmascarada as tarjeta_enmascarada,bin,replace(trim(arn),'-','') as pdaren from """||var_project_storage||"""."""||var_dataset_raw_dataentry_operaciones||"""."""||var_table_rol500_outgoing||"""
      union all
      select tarjeta_enmascarada,bin,replace(trim(arn),'-','') from """||var_project_storage||"""."""||var_dataset_raw_dataentry_operaciones||"""."""||var_table_rol500_incoming||"""
      union all
      select titarj,bin_tarj,cast(trim(tiaren) as string) from """||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcft107||"""
	  where tisitu <> 'X' and tiemis in ('99') and tifing >= '20210101' and tifing <  format_date('%Y%m%d',current_date("America/Lima")) and trim(tisist) = 'GCMS'
      union all
      select ghtarj,bin_j,cast(trim(gharen) as string) from """||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcfs108||"""
	  where ghsitu <> 'X' and ghemis in ('99') and ghfing >= '20210101' and ghfing <  format_date('%Y%m%d',current_date("America/Lima")) and trim(ghsist) = 'GCMS'
	  )
  )  
  select
    parse_date('%Y%m%d', a.pdfpro) as process_date,
    a.tarjeta_enmascarada as tarjeta_enmascarada,
    a.bin,
    nullif(upper(trim(a.pdauto)),'') as cod_autorizacion,
    nullif(trim(a.pdcest),'') as cod_comercio,
    nullif(upper(trim(a.pdmetr)),'') as tipo_canal,
    safe.parse_date('%Y%m%d', a.pdftra) as fecha_transaccion,
    nullif(trim(a.pdmone),'') as cod_moneda,
    nullif(trim(a.pdctra),'') as cod_tipo_transaccion,
    nullif(upper(trim(a.pdncom)),'') as nom_comercio,
    nullif(trim(a.pdarer),'') as arn_original,
    nullif(trim(a.pdaren),'') as arn_devolucion,
    nullif(trim(a.pdndoc),'') as voucher,
    nullif(trim(a.pdpauc),'') as cod_respuesta_ecommerce,
    nullif(upper(trim(a.pdterm)),'') as cod_terminal,
    nullif(upper(trim(c.pgdesc)),'') as metodo_ingreso,
    nullif(upper(trim(a.pdbono)),'') as referencia,
    safe_cast(a.pdimpo as float64) as mto_venta,
    nullif(upper(trim(a.pdusap)),'') as cod_usuario_aprobador,
    safe.parse_date('%Y%m%d', a.pdfaut) as fecha_autorizacion,
    format( '%s:%s:%s',lpad(substr(lpad(cast(a.pdhaut as string),6,'0'),1,2),2,'0'),lpad(substr(lpad(cast(a.pdhaut as string),6,'0'),3,2),2,'0'),lpad(substr(lpad(cast(a.pdhaut as string),6,'0'),5,2),2,'0')) as hora_autorizacion,
    safe.parse_datetime('%Y%m%d %H:%M:%S',format('%s %s:%s:%s',a.pdfaut,substr(lpad(a.pdhaut,6,'0'),1,2),substr(lpad(a.pdhaut,6,'0'),3,2),substr(lpad(a.pdhaut,6,'0'),5,2))) as fecha_hora_autorizacion,
    'AS400, VISA ONLINE' as record_source,
    current_datetime("America/Lima") as load_date,
    session_user() as creation_user
  from """||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcfs005al||""" a
  inner join contracargo b on a.tarjeta_enmascarada = b.tarjeta_enmascarada and a.pdaren = b.pdaren
  left join """||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcfv075||""" c on trim(c.pgtipo) = 'MET' and trim(c.pgcodi)  = a.pdmetr 
  where a.process_date >= '2024-09-01'
  and a.pdctra in ('76','77','78');  
  """;

  EXECUTE IMMEDIATE query;

  /************************************************************
   * Paso 2: Validar si la temporal tiene contenido
   ************************************************************/
  SET query = """
    select count(1)
    from """||var_project_operation||"""."""||var_dataset_master_stage_risk||"""."""||var_table_tmp||"""
  """;
  EXECUTE IMMEDIATE query INTO cant;

  /************************************************************
   * Paso 3: Si hay datos, truncar e insertar
   ************************************************************/
  IF IFNULL(cant, 0) > 0 THEN
    -- Truncar destino
    SET query = """
      truncate table """||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_m_ard_as400||"""
    """;
    EXECUTE IMMEDIATE query;

    -- Insertar campos explícitamente
    SET query = """
      insert into """||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_m_ard_as400||""" (
       process_date,
       tarjeta_enmascarada,
       bin,
       cod_autorizacion,
       cod_comercio,
       tipo_canal,
       fecha_transaccion,
       cod_moneda,
       cod_tipo_transaccion,
       nom_comercio,
       arn_original,
       arn_devolucion,
       voucher,
	     cod_respuesta_ecommerce,
       cod_terminal,
       metodo_ingreso,
       referencia,
       mto_venta,
       cod_usuario_aprobador,
       fecha_autorizacion,
       hora_autorizacion,
       fecha_hora_autorizacion,
       record_source,
       load_date,
       creation_user
      )
      select
       process_date,
       tarjeta_enmascarada,
       bin,
       cod_autorizacion,
       cod_comercio,
       tipo_canal,
       fecha_transaccion,
       cod_moneda,
       cod_tipo_transaccion,
       nom_comercio,
       arn_original,
       arn_devolucion,
       voucher,
	     cod_respuesta_ecommerce,
       cod_terminal,
       metodo_ingreso,
       referencia,
       mto_venta,
       cod_usuario_aprobador,
       fecha_autorizacion,
       hora_autorizacion,
       fecha_hora_autorizacion,
       record_source,
       load_date,
       creation_user
      from """||var_project_operation||"""."""||var_dataset_master_stage_risk||"""."""||var_table_tmp||"""
    """;
    EXECUTE IMMEDIATE query;
  END IF;

  /************************************************************
   * Paso 4: Eliminar tabla temporal
   ************************************************************/
  SET query = """
    drop table """||var_project_operation||"""."""||var_dataset_master_stage_risk||"""."""||var_table_tmp||"""
  """;
  EXECUTE IMMEDIATE query;

END

