BEGIN

  DECLARE query STRING;

  DECLARE var_dataset_master_risk STRING;
  DECLARE var_dataset_raw_dataentry_investigaciones STRING;
  DECLARE var_table_m_excluido_blacklist STRING;
  DECLARE var_table_base_excluidos STRING;

  SET var_dataset_master_risk = 'master_risk';
  SET var_dataset_raw_dataentry_investigaciones = 'raw_dataentry_investigaciones';
  SET var_table_m_excluido_blacklist = 'm_excluido_blacklist';
  SET var_table_base_excluidos = 'base_excluidos';

/*
  DECLARE var_project_storage STRING;

  SET var_project_storage = 'prd-izipay-data-storage-pv';
*/


SET query = """
merge into `"""||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_m_excluido_blacklist||"""` a 
using 
  (
    select 
      codigo,
      min(process_date) as process_date,
      'ANÁLISIS ÁREA INVESTIGACIONES' as record_source,
      current_datetime('America/Lima') as load_date,
      session_user() as creation_user
    from `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_investigaciones||"""."""||var_table_base_excluidos||"""`
    group by all
  ) b on (a.cod_comercio = b.codigo)
when not matched then
insert 
(
  process_date, 
  cod_comercio, 
  record_source, 
  load_date, 
  creation_user
)
values 
(
  b.process_date, 
  b.codigo, 
  b.record_source,
  b.load_date,
  b.creation_user
  )
""";
EXECUTE IMMEDIATE(query);


END

