definicion_sql:
BEGIN

  DECLARE query STRING;

  DECLARE var_dataset_master_risk STRING;
  DECLARE var_dataset_raw_as400 STRING;
  DECLARE var_table_m_retencion_abono_izpa STRING;
  DECLARE var_table_mcft044t STRING;
  DECLARE var_table_mcfv004 STRING;
  DECLARE var_table_mcfm019i STRING;
  DECLARE var_table_mcfv017 STRING;
  DECLARE var_dataset_secure_secrets STRING;
  DECLARE var_table_config_protected_data STRING;


  SET var_dataset_master_risk = 'master_risk';
  SET var_dataset_raw_as400 = 'raw_as400';
  SET var_table_m_retencion_abono_izpa = 'm_retencion_abono_izpa';
  SET var_table_mcft044t = 'mcft044t';
  SET var_table_mcfv004 = 'mcfv004';
  SET var_table_mcfm019i = 'mcfm019i';
  SET var_table_mcfv017 = 'mcfv017';

  SET var_dataset_secure_secrets = 'secure_secrets';
  SET var_table_config_protected_data = 'config_protected_data';

/*
  DECLARE var_project_storage STRING;
  DECLARE var_project_sensitive STRING;

  SET var_project_storage = 'prd-izipay-data-storage-pv';
  SET var_project_sensitive = 'prd-izipay-data-sensitive';
*/


SET query = """
truncate table `"""||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_m_retencion_abono_izpa||"""`
""";
EXECUTE IMMEDIATE(query);

SET query = """
  insert into `"""||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_m_retencion_abono_izpa||"""` 
  (
    process_date,
    cod_banco,
    nom_banco,
    party_id_izi,
    cod_comercio,
    razon_social,
    nro_cuenta,
    mto_venta,
    mto_venta_sol,
    cod_moneda,
    tipo_cambio,
    cod_proc_retencion,
    fecha_proceso,
    fecha_abono,
    tipo_cuenta,
    tercero_involucrado,
    cod_cta_especial,
    cod_situacion,
    record_source,
    load_date,
    creation_user
  )
  select 
    t044t.process_date as process_date,
    lpad(trim(t044t.pebcop),3,'0') as cod_banco,
    nullif(upper(trim(v004.badeco)),'') as nom_banco,
    t044t.party_id_izi as party_id_izi,
    trim(t044t.pecest) as cod_comercio,
    AEAD.ENCRYPT(cfu.key, coalesce(nullif(trim(AEAD.DECRYPT_STRING(cac.key, m019i.mechqn, cac.constant)),''),nullif(trim(AEAD.DECRYPT_STRING(cfu.key, m019i.mersoc, cfu.constant)),'')), cfu.constant) as razon_social,
    t044t.peccch as nro_cuenta,
    cast(t044t.penet3 as float64) as mto_venta,
    case		
      when trim(t044t.pemone) = '840' then round(cast(t044t.penet3 as float64) * cast(v017.ovven as float64), 2)
      else round(cast(t044t.penet3 as float64), 2) end as mto_venta_sol,
    nullif(trim(t044t.pemone),'') as cod_moneda,
    cast(v017.ovven as float64) as tipo_cambio,
    nullif(trim(t044t.peprod),'') as cod_proc_retencion,
    parse_date('%Y%m%d', t044t.pefpro) as fecha_proceso,
    parse_date('%Y%m%d', t044t.pefabo) as fecha_abono,
    nullif(upper(trim(t044t.petcta)),'') as tipo_cuenta,
    nullif(trim(t044t.pepagt),'') as tercero_involucrado,
    nullif(trim(t044t.pectes),'') as cod_cta_especial,
    nullif(upper(trim(t044t.pesitu)),'') as cod_situacion,
    'AS400' as record_source,  
    cast(current_datetime('America/Lima') as timestamp) as load_date,
    session_user() as creation_user
  from `"""||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcft044t||"""` as t044t
  inner join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` cac on 1=1 and cac.code = 'C_ACCOUNT_NUMBER'
