    nullif(upper(trim(v004.badeco)),'') as nom_banco,
    t044t.party_id_izi as party_id_izi,
    trim(t044t.pecest) as cod_comercio,
    AEAD.ENCRYPT(cfu.key, coalesce(nullif(trim(AEAD.DECRYPT_STRING(cac.key, m019i.mechqn, cac.constant)),''),nullif(trim(AEAD.DECRYPT_STRING(cfu.key, m019i.mersoc, cfu.constant)),'')), cfu.constant) as razon_social,
    t044t.peccch as nro_cuenta,
    cast(t044t.penet3 as float64) as mto_venta,
    case		
      when trim(t044t.pemone) = '840' then round(cast(t044t.penet3 as float64) * cast(v017.ovven as float64), 2)
      else round(cast(t044t.penet3 as float64), 2) end as mto_venta_sol,
    nullif(trim(t044t.pemone),'') as cod_moneda,
    cast(v017.ovven as float64) as tipo_cambio,
    nullif(trim(t044t.peprod),'') as cod_proc_retencion,
