    session_user() as creation_user
  from `"""||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcft044t||"""` as t044t
  inner join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` cac on 1=1 and cac.code = 'C_ACCOUNT_NUMBER'
  inner join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` cfu on 1=1 and cfu.code = 'C_FULL_NAME'
  left join `"""||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcfv004||"""` as v004 on t044t.pebcop = v004.bacodi
  left join `"""||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcfm019i||"""` as m019i on t044t.pecest = m019i.mecest
  left join `"""||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcfv017||"""` as v017 
    on t044t.process_date = v017.process_date 
      and v017.occia = '99' 
