CREATE PROCEDURE `prd-izipay-data-operation`.master_stage_risk.prc_load_table_m_retencion_fraude_crm(var_project_storage STRING)
BEGIN

  DECLARE query STRING;

  DECLARE var_dataset_master_risk STRING;
  DECLARE var_table_m_retencion_fraude_crm STRING;

  DECLARE var_dataset_raw_salesforce STRING;
  DECLARE var_table_case STRING;
  DECLARE var_table_ip4i_codigo_comercio__c STRING;
  DECLARE var_table_user STRING;

  SET var_dataset_master_risk = 'master_risk';
  SET var_table_m_retencion_fraude_crm = 'm_retencion_fraude_crm';

  SET var_dataset_raw_salesforce = 'raw_salesforce';
  SET var_table_case = 'case';
  SET var_table_ip4i_codigo_comercio__c = 'ip4i_codigo_comercio__c';
  SET var_table_user = 'user';

/*
DECLARE var_project_storage STRING;

SET var_project_storage = 'prd-izipay-data-storage-pv';
*/


SET query = """
truncate table `"""||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_m_retencion_fraude_crm||"""` 
""";
EXECUTE IMMEDIATE(query);

SET query = """
  insert into `"""||var_project_storage||"""."""||var_dataset_master_risk||"""."""||var_table_m_retencion_fraude_crm||"""` 
  (
    process_date,
    titulo_caso,
    cod_comercio,
    nom_comercio,
    tipo_caso,
    origen_caso,
    estado_caso,
    num_caso,
    nivel_prioridad_caso,
    nom_agente_caso,
    fecha_hora_creacion_caso,
    nom_usuario_mod_caso,
    fecha_mod_caso,
    record_source,
    load_date,
    creation_user
  )
  select
    current_date('America/Lima')-1 as process_date,
    upper(trim(a.subject)) as titulo_caso,
    right(b.ip4i_c_digo_comercio__c,7) as cod_comercio,
    upper(trim(b.ip4i_nombre_establecimiento__c)) as nom_comercio,
    upper(trim(a.izis_casetype__c)) as tipo_caso,
    upper(trim(a.origin)) as origen_caso,
    case 
      when a.status = 'Resuelto' then 'RESUELTO'
      when a.status = 'Closed' then 'CERRADO'
      when a.status = 'Cancelado' then 'CANCELADO'
      when a.status = 'In Progress' then 'EN PROGRESO'
      when a.status = 'New' then 'NUEVO'
      when a.status = 'Completado' then 'COMPLETADO'
      else a.status end as estado_caso,
    upper(trim(a.casenumber)) as num_caso,
    case 
      when a.priority in ('Medium','Media') then 'MEDIA'
      when a.priority = 'Low' then 'BAJA'
      when a.priority = 'High' then 'ALTA'
      end as nivel_prioridad_caso,
    c.name as nom_agente_caso,
    timestamp(datetime(timestamp(a.createddate), 'America/Lima')) as fecha_hora_creacion_caso,
    d.name as nom_usuario_mod_caso,
    timestamp(datetime(timestamp(a.lastmodifieddate), 'America/Lima')) as fecha_mod_caso,
    'CRM-SALESFORCE' as record_source,
    cast(current_datetime('America/Lima') as timestamp) as load_date,
    session_user() as creation_user
  from `"""||var_project_storage||"""."""||var_dataset_raw_salesforce||"""."""||var_table_case||"""` a
  left join `"""||var_project_storage||"""."""||var_dataset_raw_salesforce||"""."""||var_table_ip4i_codigo_comercio__c||"""` b on (a.gsc_shops__c = b.id)
  left join `"""||var_project_storage||"""."""||var_dataset_raw_salesforce||"""."""||var_table_user||"""` c on (a.createdbyid = c.id)
  left join `"""||var_project_storage||"""."""||var_dataset_raw_salesforce||"""."""||var_table_user||"""` d on (a.lastmodifiedbyid = d.id)
  where
    upper(subject) like any ('%FRAUDE%')
""";
EXECUTE IMMEDIATE(query);



END;

definicion_sql:
BEGIN
  DECLARE query STRING;
  DECLARE cant INT64;
  DECLARE var_table_tmp_t_99_afiliaciones_cot STRING;
  DECLARE var_fecha_ini DATE;
  DECLARE var_fecha_fin DATE;
/*
DECLARE var_project_operation STRING;
DECLARE var_project_storage STRING;


SET var_project_operation = 'prd-izipay-data-operation';
SET var_project_storage = 'prd-izipay-data-storage-pv';

*/

  DECLARE var_dataset_master_stage_transaction STRING;
  DECLARE var_dataset_master_transaction STRING;
  DECLARE var_table_t_99_afiliaciones_cot STRING;
  DECLARE var_dataset_bq_omni_azure_izipay STRING;

  SET var_dataset_master_stage_transaction = 'master_stage_transaction';
  SET var_dataset_master_transaction = 'master_transaction';
  SET var_table_t_99_afiliaciones_cot = 't_99_afiliaciones_cot';
  SET var_dataset_bq_omni_azure_izipay = 'bq_omni_izipay_azure_saizipaydatamarts';


  SET var_table_tmp_t_99_afiliaciones_cot = concat('tmp_',var_table_t_99_afiliaciones_cot);

  /* Verificar si la tabla EXTERNA tiene contenido, guardar el conteo*/
  SET query = """
   select count(1)
   from `"""||var_project_operation||"""."""||var_dataset_bq_omni_azure_izipay||"""."""||var_table_t_99_afiliaciones_cot||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN
      /* Crear una tabla temporal con los datos sumando las columnas adicionales para auditoria*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_master_stage_transaction||"""."""||var_table_tmp_t_99_afiliaciones_cot||"""` as
        select
          parse_date('%Y%m%d',cast(fecha_apertura as string)) as process_date,
          cast(periodo_apertura as string) as periodo_apertura,
          cast(codigo as string) as codigo,
          cast(nro_ruc as string) as nro_ruc,
          cast(party_id as string) as party_id,
