/*
  DECLARE var_project_operation STRING;
  DECLARE var_project_storage STRING;

  SET var_project_operation = 'dev-izipay-data-operation';
  SET var_project_storage = 'dev-izipay-data-storage';
*/

  SET var_table_tmp_mcfv1007 = concat('tmp_',var_table_mcfv1007);

  /* Verificar si la tabla EXTERNA tiene contenido, guardar el conteo*/
  SET query = """
   select count(1)
   from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_mcfv1007||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN

      /* Crear una tabla temporal con los datos sumando las columnas adicionales para auditoria*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_raw_stage_as400||"""."""||var_table_tmp_mcfv1007||"""` as
        select
          cast(ocide as string) as ocide,
          cast(occia as string) as occia,
          cast(ocsuc as string) as ocsuc,
          cast(ocmon as string) as ocmon,
          cast(olcot as string) as olcot,
          cast(ofano as string) as ofano,
          right(concat('00',cast(ofmes as string)),2) as ofmes,
          right(concat('00',cast(ofdia as string)),2) as ofdia,
          cast(ovcom as string) as ovcom,
          cast(ovven as string) as ovven,
          cast(ofill as string) as ofill,
          cast(ofmod as string) as ofmod,
          cast(ohmod as string) as ohmod,
          cast(ocusr as string) as ocusr,
          parse_date('%Y%m%d',concat(cast(ofano as string),right(concat('00',cast(ofmes as string)),2),right(concat('00',cast(ofdia as string)),2))) as process_date,
          'as400' as record_source,
          cast(current_datetime('America/Lima') as timestamp) as load_date
        from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_mcfv1007||"""` 
      """;
      EXECUTE IMMEDIATE(query);

      EXECUTE IMMEDIATE """ select min(process_date),max(process_date)
      FROM `"""||var_project_operation||"""."""||var_dataset_raw_stage_as400||"""."""||var_table_tmp_mcfv1007||"""`
      """
      into var_fecha_ini,var_fecha_fin;

      /* Truncar la tabla destino antes de insertar los nuevos datos*/
      SET query = """
      DELETE FROM `"""||var_project_operation||"""."""||var_dataset_raw_stage_as400||"""."""||var_table_tmp_mcfv1007||"""`
      WHERE process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'  
      """;
      EXECUTE IMMEDIATE(query);

      /* Insertar los datos desde la tabla temporal a la tabla destino*/
      SET query = """
        insert into `"""||var_project_storage||"""."""||var_dataset_raw_as400||"""."""||var_table_mcfv1007||"""` 
        (
          ocide,
          occia,
          ocsuc,
          ocmon,
          olcot,
          ofano,
          ofmes,
          ofdia,
          ovcom,
          ovven,
          ofill,
          ofmod,
          ohmod,
          ocusr,
          process_date,
          record_source,
          load_date,
          creation_user
        )
        select
