  SET var_dataset_secure_secrets = 'secure_secrets';
  SET var_dataset_master_pii = 'master_pii';
  SET var_table_config_protected_data = 'config_protected_data';
  SET var_table_itc_iden_party_data_control = 'iden_party_data_control';

/*
  DECLARE var_project_operation STRING;
  DECLARE var_project_storage STRING;
  DECLARE var_project_sensitive STRING; --prd-izipay-data-sensitive --> proyecto independiente

  SET var_project_operation = 'prd-izipay-data-operation';
  SET var_project_storage = 'prd-izipay-data-storage-pv';
  SET var_project_sensitive = 'prd-izipay-data-sensitive';


  */

  SET var_table_tmp_auth_user = concat('tmp_',var_table_auth_user);

  /* Verificar si la tabla EXTERNA tiene contenido, guardar el conteo*/
  SET query = """
   select count(1)
   from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_auth_user||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN

      /* Crear una tabla temporal con los datos sumando las columnas adicionales para auditoria*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_raw_stage_compraya||"""."""||var_table_tmp_auth_user||"""` as
        select
          current_date ('America/Lima') as process_date
          ,cast(date_joined as string) as date_joined
          ,cast(is_active as string) as is_active
          ,cast(is_staff as string) as is_staff
          ,cast(email as string) as email
          ,cast(last_name as string) as last_name
          ,cast(first_name as string) as first_name
          ,cast(username as string) as username
          ,cast(is_superuser as string) as is_superuser
          ,cast(last_login as string) as last_login
          ,cast(password as string) as password
          ,cast(id as string) as id
          ,'compraya' as record_source
          ,cast(current_datetime('America/Lima') as timestamp) as load_date
        from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_auth_user||"""`
      """;
      EXECUTE IMMEDIATE(query);

      /* Truncar la tabla destino antes de insertar los nuevos datos*/
      SET query = """
        truncate table `"""||var_project_storage||"""."""||var_dataset_raw_compraya||"""."""||var_table_auth_user||"""` 
      """;
      EXECUTE IMMEDIATE(query);

      /* Insertar los datos desde la tabla temporal a la tabla destino*/
      SET query = """
        insert into `"""||var_project_storage||"""."""||var_dataset_raw_compraya||"""."""||var_table_auth_user||"""` 
        (
        process_date
        ,id
        ,password
        ,last_login
        ,is_superuser
        ,username
        ,first_name
        ,last_name
        ,email
        ,is_staff
        ,is_active
        ,date_joined
        ,record_source
        ,load_date
        ,creation_user
        )
        select
          a.process_date
        ,a.id
        ,a.password
        ,a.last_login 
        ,a.is_superuser
        ,a.username
        ,AEAD.ENCRYPT(b.key, a.first_name, b.constant)
        ,AEAD.ENCRYPT(c.key, a.last_name, c.constant)
        ,AEAD.ENCRYPT(d.key, a.email, d.constant)
        ,a.is_staff
        ,a.is_active
        ,a.date_joined
        ,a.record_source
        ,a.load_date
          ,session_user() as creation_user
        from `"""||var_project_operation||"""."""||var_dataset_raw_stage_compraya||"""."""||var_table_tmp_auth_user||"""` a
       left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` b on b.code = 'C_NAME'
        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` c on c.code = 'C_LAST_NAME'
        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` d on d.code = 'C_EMAIL'
--       left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` e on e.code = 'C_CELL_PHONE'
--        left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_itc_iden_party_data_control||"""` f on (trim(a.document_number) = f.document_number)
--        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` g on g.code = 'C_TELEPHONE'
--        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` h on h.code = 'C_ADDRESS'
--        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` i on i.code = 'C_ACCOUNT_NUMBER'
--        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` j on j.code = 'C_ACCOUNT_NUMBER'
      """;
      EXECUTE IMMEDIATE(query);

      /* Eliminar la tabla temporal*/
      SET query = """
        drop table `"""||var_project_operation||"""."""||var_dataset_raw_stage_compraya||"""."""||var_table_tmp_auth_user||"""`
      """;
      EXECUTE IMMEDIATE(query);

  END IF;
END

