CREATE PROCEDURE `prd-izipay-data-operation`.raw_stage_dataentry_arisale.prc_load_arisale_devices(var_project_operation STRING, var_project_storage STRING, var_project_sensitive STRING)
BEGIN
  DECLARE query STRING;
  DECLARE cant INT64;
  DECLARE var_table_tmp_devices STRING;
  DECLARE var_process_date DATE;

  DECLARE var_dataset_raw_stage_dataentry_arisale STRING;
  DECLARE var_dataset_raw_dataentry_arisale STRING;
  DECLARE var_table_omni_devices STRING;
  DECLARE var_table_devices STRING;
  DECLARE var_table_h_devices STRING;
  DECLARE var_dataset_bq_omni_izipay_azure STRING;  
  DECLARE var_dataset_secure_secrets STRING;
  DECLARE var_dataset_master_pii STRING;
  DECLARE var_table_config_protected_data STRING;
  DECLARE var_table_itc_iden_party_data_control STRING;

  SET var_dataset_raw_stage_dataentry_arisale = 'raw_stage_dataentry_arisale';
  SET var_dataset_raw_dataentry_arisale = 'raw_dataentry_arisale';
  SET var_table_devices = 'devices';
  SET var_table_h_devices = 'devices_h';
  SET var_dataset_bq_omni_izipay_azure = 'bq_omni_izipay_azure_saizipaydatamarts';
  SET var_dataset_secure_secrets = 'secure_secrets';
  SET var_dataset_master_pii = 'master_pii';
  SET var_table_config_protected_data = 'config_protected_data';
  SET var_table_itc_iden_party_data_control = 'iden_party_data_control';

/*
  DECLARE var_project_operation STRING;
  DECLARE var_project_storage STRING;
  DECLARE var_project_sensitive STRING; --prd-izipay-data-sensitive --> proyecto independiente

  SET var_project_operation = 'dev-izipay-data-operation';
  SET var_project_storage = 'dev-izipay-data-storage';
  SET var_project_sensitive = 'dev-izipay-data-storage';
  */

  SET var_table_tmp_devices = concat('tmp_',var_table_devices);

  /* Verificar si la tabla EXTERNA tiene contenido, guardar el conteo*/
  SET query = """
   select count(1)
   from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_devices||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN

      /* Crear una tabla temporal con los datos sumando las columnas adicionales para auditoria*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_arisale||"""."""||var_table_tmp_devices||"""` as
        select
          NULLIF(TRIM(cast(Tipo_de_documento_Comercio as string)), '') as tipo_doc,
          NULLIF(TRIM(cast(Documento_de_identidad_Comercio as string)), '') as party_id_izi,
          NULLIF(TRIM(Razon_social_Comercio), '') as razon_social,
          NULLIF(TRIM(cast(Nombre_comercial_Comercio as string)), '') as nom_comercio,
          NULLIF(TRIM(cast(Numero_de_serie_terminal as string)), '') as nro_serie,
          parse_date('%d/%m/%Y', NULLIF(TRIM(cast(Fecha_afiliacion as string)), '')) as fecha_afiliacion,
          SAFE.PARSE_DATE(
            '%d/%m/%Y',
            NULLIF(
              NULLIF(TRIM(cast(Fecha_de_desafiliacion as string)), ''),
              '-'
            )
          ) as fecha_desafiliacion,
          NULLIF(TRIM(cast(Estado as string)), '') as estado,
          current_date("America/Lima") as process_date,
          'ARISALE' as record_source,
          current_datetime('America/Lima') as load_date
        from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_devices||"""`
      """;
      EXECUTE IMMEDIATE(query);

      /* Truncar la tabla destino antes de insertar los nuevos datos*/
      SET query = """
        truncate table `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_devices||"""` 
      """;
      EXECUTE IMMEDIATE(query);

      /* Insertar los datos desde la tabla temporal a la tabla destino*/
      SET query = """
        insert into `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_devices||"""` 
        (
          tipo_doc,
          party_id_izi,
          razon_social,
          nom_comercio,
          nro_serie,
          fecha_afiliacion,
          fecha_desafiliacion,
          estado,
          process_date,
          record_source,
          load_date,
          creation_user
        )
        select
          a.tipo_doc as tipo_doc,
          b.party_id_izi as party_id_izi,
          AEAD.ENCRYPT(c.key,a.razon_social, c.constant) as razon_social,
          a.nom_comercio as nom_comercio,
          a.nro_serie,
          a.fecha_afiliacion,
          a.fecha_desafiliacion,
          a.estado,
          a.process_date,
          a.record_source,
          a.load_date,
          session_user() as creation_user
        from `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_arisale||"""."""||var_table_tmp_devices||"""` a
        left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_itc_iden_party_data_control||"""` b on trim(a.party_id_izi) = b.document_number
        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` c on c.code = 'C_BUSINESS_NAME'
      """;
      EXECUTE IMMEDIATE(query);

      /* Obtengo el process_date actual de la tabla temporal y lo guardo en una variable */
      SET query = """
        SELECT DISTINCT process_date
        FROM `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_arisale||"""."""||var_table_tmp_devices||"""`
        LIMIT 1
      """;
      EXECUTE IMMEDIATE query 
      INTO var_process_date;

      /* Eliminar la tabla temporal*/
      SET query = """
        drop table `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_arisale||"""."""||var_table_tmp_devices||"""`
      """;
      EXECUTE IMMEDIATE(query);

      /* Borrar datos de la tabla historica pero segun la variable del process_date*/
      SET query = """
        DELETE FROM `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_h_devices||"""`
          WHERE process_date = @process_date
      """;
      EXECUTE IMMEDIATE(query)
      USING var_process_date AS process_date;

      SET query = """
        INSERT INTO `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_h_devices||"""`
        (
          tipo_doc,
          party_id_izi,
          razon_social,
          nom_comercio,
          nro_serie,
          fecha_afiliacion,
          fecha_desafiliacion,
          estado,
          process_date,
          record_source,
          load_date,
          creation_user
        )
        SELECT * FROM `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_devices||"""` 
      """;
      EXECUTE IMMEDIATE(query);
  END IF;
END;

