  SET var_project_operation = 'dev-izipay-data-operation';
  SET var_project_storage = 'dev-izipay-data-storage';
  SET var_project_sensitive = 'dev-izipay-data-storage';
  */

  SET var_table_tmp_usages = concat('tmp_',var_table_usages);

  /* Verificar si la tabla EXTERNA tiene contenido, guardar el conteo*/
  SET query = """
   select count(1)
   from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_usages||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN

      /* Crear una tabla temporal con los datos sumando las columnas adicionales para auditoria*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_arisale||"""."""||var_table_tmp_usages||"""` as
        select
          NULLIF(TRIM(cast(Tipo_de_documento as string)), '') as tipo_doc,
          NULLIF(TRIM(cast(Documento_de_identidad as string)), '') as party_id_izi,
          NULLIF(TRIM(Razon_social), '') as razon_social,
          NULLIF(TRIM(cast(Nombre_comercial as string)), '') as nom_comercio,
          NULLIF(TRIM(cast(Realizar_Venta as string)), '') as flg_venta,
          NULLIF(TRIM(cast(Venta_Rapida as string)), '') as flg_venta_rapida,
          NULLIF(TRIM(cast(Toma_Pedidos as string)), '') as flg_toma_pedidos,
          NULLIF(TRIM(cast(Inventario as string)), '') as flg_gestion_invent,
          NULLIF(TRIM(cast(Cuenta_por_cobrar as string)), '') as flg_cuentas_cobrar,
          NULLIF(TRIM(cast(Compras as string)), '') as flg_compras,
          NULLIF(TRIM(cast(Cuentas_por_pagar as string)), '') as flg_cuentas_pagar,
