          current_date("America/Lima") as process_date,
          'ARISALE' as record_source,
          current_datetime('America/Lima') as load_date
        from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_usages||"""`
      """;
      EXECUTE IMMEDIATE(query);

      /* Truncar la tabla destino antes de insertar los nuevos datos*/
      SET query = """
        truncate table `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_usages||"""` 
      """;
      EXECUTE IMMEDIATE(query);

      /* Insertar los datos desde la tabla temporal a la tabla destino*/
      SET query = """
        insert into `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_usages||"""` 
        (
          tipo_doc,
          party_id_izi,
          razon_social,
          nom_comercio,
          flg_venta,
          flg_venta_rapida,
          flg_toma_pedidos,
          flg_gestion_invent,
          flg_cuentas_cobrar,
          flg_compras,
          flg_cuentas_pagar,
          flg_ordenes,
          flg_sunat,
          process_date,
          record_source,
          load_date,
          creation_user
        )
        select
          a.tipo_doc as tipo_doc,
          b.party_id_izi as party_id_izi,
          AEAD.ENCRYPT(c.key,a.razon_social, c.constant) as razon_social,
          a.nom_comercio as nom_comercio,
          a.flg_venta,
          a.flg_venta_rapida,
          a.flg_toma_pedidos,
          a.flg_gestion_invent,
          a.flg_cuentas_cobrar,
          a.flg_compras,
          a.flg_cuentas_pagar,
          a.flg_ordenes,
          a.flg_sunat,
          a.process_date,
          a.record_source,
          a.load_date,
          session_user() as creation_user
        from `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_arisale||"""."""||var_table_tmp_usages||"""` a
        left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_itc_iden_party_data_control||"""` b on trim(a.party_id_izi) = b.document_number
        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` c on c.code = 'C_BUSINESS_NAME'
      """;
      EXECUTE IMMEDIATE(query);

      /* Obtengo el process_date actual de la tabla temporal y lo guardo en una variable */
      SET query = """
        SELECT DISTINCT process_date
        FROM `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_arisale||"""."""||var_table_tmp_usages||"""`
        LIMIT 1
      """;
      EXECUTE IMMEDIATE query 
      INTO var_process_date;

      /* Eliminar la tabla temporal*/
      SET query = """
        drop table `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_arisale||"""."""||var_table_tmp_usages||"""`
      """;
      EXECUTE IMMEDIATE(query);

      /* Borrar datos de la tabla historica pero segun la variable del process_date*/
      SET query = """
        DELETE FROM `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_h_usages||"""`
          WHERE process_date = @process_date
      """;
      EXECUTE IMMEDIATE(query)
      USING var_process_date AS process_date;

      SET query = """
        INSERT INTO `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_h_usages||"""`
        (
          tipo_doc,
          party_id_izi,
          razon_social,
          nom_comercio,
          flg_venta,
          flg_venta_rapida,
          flg_toma_pedidos,
          flg_gestion_invent,
          flg_cuentas_cobrar,
          flg_compras,
          flg_cuentas_pagar,
          flg_ordenes,
          flg_sunat,
          process_date,
          record_source,
          load_date,
          creation_user
        )
        SELECT * FROM `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_arisale||"""."""||var_table_usages||"""` 
      """;
      EXECUTE IMMEDIATE(query);
  END IF;
END

