  SET query = """
   select count(1)
   from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_bl_afiliacion_arisale||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN

      /* Se crea la tabla temporal*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_cx||"""."""||var_table_tmp_afiliacion_arisale||"""` as 
        select 
          parse_date('%d/%m/%Y', fecha_proceso) as process_date
          ,cast(fecha_proceso as string) as fecha_proceso
          ,cast(codigo as string) as codigo
          ,cast(ruc as string) as ruc
          ,cast(razon_social as string) as razon_social
          ,cast(datos_cliente as string) as datos_cliente
          ,cast(telefono as string) as telefono
          ,cast(tipo_de_cliente as string) as tipo_de_cliente
          ,cast(plan_ari as string) as plan_ari
          ,cast(licencia_activa as string) as licencia_activa
          ,cast(credenciales_enviadas as string) as credenciales_enviadas
          ,cast(tipo_venta as string) as tipo_venta
          ,cast(p_canal as string) as p_canal
          ,'data_entry_cx' as record_source
          ,cast(current_datetime('America/Lima') as timestamp) as load_date
        from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_bl_afiliacion_arisale||"""` 
      """;
      EXECUTE IMMEDIATE(query);

      /* Obtener el rango de fecha a insertar*/
      EXECUTE IMMEDIATE """ select min(process_date),max(process_date)
      FROM `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_cx||"""."""||var_table_tmp_afiliacion_arisale||"""`
      """
      into var_fecha_ini, var_fecha_fin;

