          ,telefono
          ,tipo_de_cliente
          ,plan_ari
          ,licencia_activa
          ,credenciales_enviadas
          ,tipo_venta
          ,p_canal
          ,record_source
          ,load_date
          ,creation_user
        )
        select
          ifnull(a.process_date,'2024-01-01') as process_date
          ,a.fecha_proceso
          ,a.codigo
          ,b.party_id_izi --a.ruc
          ,a.razon_social
          ,AEAD.ENCRYPT(c.key, a.datos_cliente, c.constant) as datos_cliente --a.datos_cliente
          ,AEAD.ENCRYPT(d.key, a.telefono, d.constant) as telefono --a.telefono
          ,a.tipo_de_cliente
          ,a.plan_ari
          ,a.licencia_activa
          ,a.credenciales_enviadas
          ,a.tipo_venta
          ,a.p_canal
          ,a.record_source
          ,a.load_date
          ,session_user() as creation_user
        from `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_cx||"""."""||var_table_tmp_afiliacion_arisale||"""` a 
        left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_itc_iden_party_data_control||"""` b on (trim(a.ruc) = b.document_number)

        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` c on (c.code = 'C_FULL_NAME')
        left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` d on (d.code = 'C_CELL_PHONE')
      """;
      EXECUTE IMMEDIATE(query);


      SET query = """
        create or replace table `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_cx||"""."""||var_table_afiliacion_arisale||"""_stage` as
        select
          ifnull(a.process_date,'2024-01-01') as process_date
          ,a.fecha_proceso
          ,a.codigo
          ,b.party_id_izi --a.ruc
          ,a.razon_social
          ,AEAD.ENCRYPT(c.key, a.datos_cliente, c.constant) as datos_cliente --a.datos_cliente
          ,AEAD.ENCRYPT(d.key, a.telefono, d.constant) as telefono --a.telefono
          ,a.tipo_de_cliente
          ,a.plan_ari
          ,a.licencia_activa
          ,a.credenciales_enviadas
          ,a.tipo_venta
          ,a.p_canal
          ,a.record_source
          ,a.load_date
          ,session_user() as creation_user
        from `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_cx||"""."""||var_table_tmp_afiliacion_arisale||"""` a 
