      """;
      EXECUTE IMMEDIATE(query);

      /* Insertar los datos desde la tabla temporal a la tabla destino*/
      SET query = """
        insert into `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_cx||"""."""||var_table_afiliacion_arisale||"""` 
        (
          process_date
          ,fecha_proceso
          ,codigo
