  SET var_project_operation = 'prd-izipay-data-operation';
  SET var_project_storage = 'prd-izipay-data-storage-pv';
  SET var_project_sensitive = 'prd-izipay-data-sensitive';
*/

  DECLARE var_dataset_raw_stage_dataentry_data STRING;
  DECLARE var_dataset_raw_dataentry_data STRING;
  DECLARE var_table_pt_cuboproducto STRING;
  DECLARE var_dataset_bq_omni_izipay_azure STRING;

  DECLARE var_dataset_master_pii STRING;
  DECLARE var_table_iden_party_data_control STRING;
  DECLARE var_dataset_secure_secrets STRING;
  DECLARE var_table_config_protected_data STRING;

  SET var_fecha = current_date('America/Lima')-1;

  SET var_dataset_raw_stage_dataentry_data = 'raw_stage_dataentry_data';
  SET var_dataset_raw_dataentry_data = 'raw_dataentry_data';
  SET var_table_pt_cuboproducto = 'pt_cuboproducto';
  SET var_dataset_bq_omni_izipay_azure = 'bq_omni_izipay_azure_saizipaydatamarts';

  SET var_dataset_master_pii = 'master_pii';
  SET var_table_iden_party_data_control = 'iden_party_data_control';
  SET var_dataset_secure_secrets = 'secure_secrets';
  SET var_table_config_protected_data = 'config_protected_data';


  SET var_table_tmp_pt_cuboproducto = concat('tmp_',var_table_pt_cuboproducto);


  /* Verificar si la tabla EXTERNA tiene contenido, guardar el conteo*/
  SET query = """
  select count(1)
  from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_pt_cuboproducto||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN

      /* Crear una tabla temporal con los datos sumando las columnas adicionales para auditoria*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_data||"""."""||var_table_tmp_pt_cuboproducto||"""` as
          select
            cast(producto as string) as producto,
            cast(subproducto as string) as subproducto,
            cast(marca as string) as marca,
            cast(pdprod as string) as pdprod,
            cast(pdspro as string) as pdspro,
            date('"""||var_fecha||"""') as process_date,
            'CARGA ÚNICA' as record_source,
            current_datetime('America/Lima') as load_date
          from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_pt_cuboproducto||"""` 
      """;
      EXECUTE IMMEDIATE(query);

      /* Truncar la tabla destino antes de insertar los nuevos datos*/
      SET query = """
        truncate table `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_data||"""."""||var_table_pt_cuboproducto||"""` 
      """;
      EXECUTE IMMEDIATE(query);

      /* Insertar los datos desde la tabla temporal a la tabla destino*/
      SET query = """
        insert into `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_data||"""."""||var_table_pt_cuboproducto||"""` 
        (
          producto,
          subproducto,
          marca,
          pdprod,
          pdspro,
          process_date,
          record_source,
          load_date,
          creation_user
        )
        select
          a.producto,
          a.subproducto,
          a.marca,
          a.pdprod,
          a.pdspro,
          a.process_date,
          a.record_source,
          a.load_date,
          session_user() as creation_user
        from `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_data||"""."""||var_table_tmp_pt_cuboproducto||"""` a
       /* left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_iden_party_data_control||"""` b on (trim(nroruc) = b.hash_id)
        inner join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` cbu on 1=1 and cbu.code = 'C_BUSINESS_NAME'*/
      """;
      EXECUTE IMMEDIATE(query);

      /* Eliminar la tabla temporal*/
      SET query = """
        drop table `"""||var_project_operation||"""."""||var_dataset_raw_stage_dataentry_data||"""."""||var_table_tmp_pt_cuboproducto||"""`
      """;
      EXECUTE IMMEDIATE(query);

      IF var_project_operation = 'dev-izipay-data-operation' THEN
        call `dev-izipay-data-operation.master_stage.prc_load_t_monitoreo`(var_project_storage,var_project_storage,var_dataset_raw_dataentry_data,var_table_pt_cuboproducto,'maestro',var_fecha,var_fecha);
      ELSEIF var_project_operation = 'prd-izipay-data-operation' THEN
        call `prd-izipay-data-operation.master_stage.prc_load_t_monitoreo`(var_project_storage,var_project_storage,var_dataset_raw_dataentry_data,var_table_pt_cuboproducto,'maestro',var_fecha,var_fecha);
      END IF;


  END IF;

END

