BEGIN

  DECLARE query STRING;
  DECLARE cant INT64;

  DECLARE var_dataset_raw_dataentry_finanzas STRING;
  DECLARE var_dataset_raw_stage_dataentry_finanzas STRING;
  DECLARE var_table_rpta_rechazo_bbva_izipay STRING;

  DECLARE var_dataset_master_pii STRING;
  DECLARE var_table_iden_party_data_control STRING;

  DECLARE var_dataset_secure_secrets STRING;
  DECLARE var_table_config_protected_data STRING;


  SET var_dataset_raw_dataentry_finanzas = 'raw_dataentry_finanzas';
  SET var_dataset_raw_stage_dataentry_finanzas = 'raw_stage_dataentry_finanzas';
  SET var_table_rpta_rechazo_bbva_izipay = 'rpta_rechazo_bbva_izipay';

  SET var_dataset_master_pii = 'master_pii';
  SET var_table_iden_party_data_control = 'iden_party_data_control';

  SET var_dataset_secure_secrets = 'secure_secrets';
  SET var_table_config_protected_data = 'config_protected_data';

/*
  DECLARE var_project_storage STRING;
  DECLARE var_project_sensitive STRING;
  DECLARE var_fecha_ini DATE;
  DECLARE var_fecha_fin DATE;

  SET var_project_storage = 'prd-izipay-data-storage-pv';
  SET var_project_sensitive = 'prd-izipay-data-sensitive';
  SET var_fecha_ini = current_date('America/Lima');
  SET var_fecha_fin = current_date('America/Lima');
*/


  SET query = """
  delete from `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_finanzas||"""."""||var_table_rpta_rechazo_bbva_izipay||"""`
  where process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'  
  """;
  EXECUTE IMMEDIATE(query);

  SET query = """
    insert into `"""||var_project_storage||"""."""||var_dataset_raw_dataentry_finanzas||"""."""||var_table_rpta_rechazo_bbva_izipay||"""` 
    (
      comercio,
      fecha_apertura,
      tipo_documento,
      party_id_izi,
      razon_social,
      nro_cuenta,
      banco,
      moneda,
      importe,
      archivo,
      motivo_rechazo,
      process_date,
      record_source,
      load_date,
      creation_user
    )
    select
      a.comercio,
      a.fecha_apertura,
      a.tipo_documento,
      b.party_id_izi,
      a.razon_social,
      AEAD.ENCRYPT(c.key,trim(a.nro_cuenta),c.constant) as nro_cuenta,
      a.banco,
      a.moneda,
      a.importe,
      a.archivo,
      a.motivo_rechazo,
      date(a.process_date) as process_date,
      'Archivo de Rechazos' as record_source,
      cast(current_datetime('America/Lima') as timestamp) as load_date,
      session_user() as creation_user
    from `"""||var_project_storage||"""."""||var_dataset_raw_stage_dataentry_finanzas||"""."""||var_table_rpta_rechazo_bbva_izipay||"""` a 
    left join `"""||var_project_sensitive||"""."""||var_dataset_master_pii||"""."""||var_table_iden_party_data_control||"""` b on (trim(a.nro_documento) = b.document_number)
    left join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` c on c.code = 'C_ACCOUNT_NUMBER'
    where 
      a.process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
  """;
  EXECUTE IMMEDIATE(query);

  SET query = """
  drop table `"""||var_project_storage||"""."""||var_dataset_raw_stage_dataentry_finanzas||"""."""||var_table_rpta_rechazo_bbva_izipay||"""`
  """;
  EXECUTE IMMEDIATE(query);


END

