  declare var_table_bl_abonos_ibk STRING;

  SET var_dataset_raw_stage_ibk = 'raw_stage_ibk';
  SET var_dataset_raw_ibk = 'raw_ibk';
  SET var_table_abonos_ibk = 'abonos_ibk';
  SET var_dataset_bq_omni_izipay_azure = 'bq_omni_izipay_azure_saizipaydatamarts';
  SET var_table_bl_abonos_ibk = 'abonos_ibk';

/*
  DECLARE var_project_operation STRING;
  DECLARE var_project_storage STRING;
  DECLARE var_project_sensitive STRING;

  SET var_project_operation = 'prd-izipay-data-operation';
  SET var_project_storage = 'prd-izipay-data-storage-pv';
  SET var_project_sensitive = 'prd-izipay-data-sensitive';

  */

  SET var_table_tmp_abono_ibk = concat('tmp_',var_table_bl_abonos_ibk);


  /* Verificar si la tabla EXTERNA tiene contenido, guardar el conteo*/
  SET query = """
   select count(1)
   from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_bl_abonos_ibk||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN
      /* Crear una tabla temporal con los datos sumando las columnas adicionales para auditoria*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_raw_stage_ibk||"""."""||var_table_tmp_abono_ibk||"""` as
        select
          cast(nombre_rubro as string) as nombre_rubro,
          cast(nombre_corto_empresa as string) as nombre_corto_empresa,
          cast(tipo_identificacion_empresa as string) as tipo_identificacion_empresa,
          cast(fecha_informacion as string) as fecha_informacion,
          cast(horainievento_tm as string) as horainievento_tm,
          cast(fecha_proceso as string) as fecha_proceso,
          cast(tipo_abono as string) as tipo_abono,
          cast(codigo_moneda as string) as codigo_moneda,
          cast(total_abonos_soles as string) as total_abonos_soles,
          cast(total_abonos_dolares as string) as total_abonos_dolares,
          cast(empresa as string) as empresa,
          cast(inter_hash_emp as string) as inter_hash_emp,
          cast(tipo_cuenta_com as string) as tipo_cuenta_com,
          cast(fec_apertura_cta_com as string) as fec_apertura_cta_com,
          cast(ubigeo as string) as ubigeo,
          cast(pais_abono_benef as string) as pais_abono_benef,
          cast(tipo_cambio_dolar as string) as tipo_cambio_dolar,
          cast(segmento as string) as segmento,
          cast(inter_hash_id as string) as inter_hash_id_doc,
          cast(inter_hash_nro_cta as string) as inter_hash_id_nro_cta,
          parse_date('%Y-%m-%d',cast(fecha_proceso as string)) as process_date,
          'ibk' as record_source,
          cast(current_datetime('America/Lima') as timestamp) as load_date
        from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_bl_abonos_ibk||"""` 
      """;
      EXECUTE IMMEDIATE(query);

      EXECUTE IMMEDIATE """ select min(parse_date('%Y-%m-%d',cast(fecha_informacion as string))),max(parse_date('%Y-%m-%d',cast(fecha_informacion as string)))
      from `"""||var_project_operation||"""."""||var_dataset_raw_stage_ibk||"""."""||var_table_tmp_abono_ibk||"""`
      """
      into var_fecha_ini,var_fecha_fin;

      /* Truncar la tabla historica antes de insertar los nuevos datos */
      SET query = """
      delete from `"""||var_project_storage||"""."""||var_dataset_raw_ibk||"""."""||var_table_abonos_ibk||"""`
      where parse_date('%Y-%m-%d',cast(fecha_informacion as string)) between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'  
      """;
      EXECUTE IMMEDIATE(query);

      /* Insertar los datos a la tabla historica desde la tabla stage*/
      SET query = """
        insert into `"""||var_project_storage||"""."""||var_dataset_raw_ibk||"""."""||var_table_abonos_ibk||"""` 
        (
          nombre_rubro,
          nombre_corto_empresa,
          tipo_identificacion_empresa,
          fecha_informacion,
          horainievento_tm,
          fecha_proceso,
          tipo_abono,
          codigo_moneda,
          total_abonos_soles,
          total_abonos_dolares,
          empresa,
          inter_hash_emp,
          tipo_cuenta_com,
          fec_apertura_cta_com,
          ubigeo,
          pais_abono_benef,
          tipo_cambio_dolar,
          segmento,
          inter_hash_id_doc,
          inter_hash_id_nro_cta, 
          process_date,
          record_source,
          load_date,
          creation_user
        )
        select
          nombre_rubro,
          nombre_corto_empresa,
          tipo_identificacion_empresa,
          fecha_informacion,
          horainievento_tm,
          fecha_proceso,
          tipo_abono,
          codigo_moneda,
          total_abonos_soles,
          total_abonos_dolares,
          empresa,
          inter_hash_emp,
          tipo_cuenta_com,
          fec_apertura_cta_com,
          ubigeo,
          pais_abono_benef,
          tipo_cambio_dolar,
          segmento,
          inter_hash_id_doc,
          inter_hash_id_nro_cta, 
          process_date,
          record_source,
          load_date,
          session_user() as creation_user
        from `"""||var_project_operation||"""."""||var_dataset_raw_stage_ibk||"""."""||var_table_tmp_abono_ibk||"""`
      """;
      EXECUTE IMMEDIATE(query);

      /* Eliminar la tabla temporal*/
      SET query = """
        drop table `"""||var_project_operation||"""."""||var_dataset_raw_stage_ibk||"""."""||var_table_tmp_abono_ibk||"""`
      """;
      EXECUTE IMMEDIATE(query);

  END IF;
END

