        inner join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` cem on 1=1 and cem.code = 'C_EMAIL' 
        inner join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` cce on 1=1 and cce.code = 'C_CELL_PHONE' 
        where a.process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'
      """;
      EXECUTE IMMEDIATE(query);

