BEGIN
  DECLARE query STRING;
  DECLARE cant INT64;
  DECLARE var_table_tmp_bd_casos STRING;
  DECLARE var_fecha_ini DATE;
  DECLARE var_fecha_fin DATE;
  DECLARE var_dataset_secure_secrets STRING;
  DECLARE var_table_config_protected_data STRING;
  DECLARE var_dataset_raw_stage_om STRING;
  DECLARE var_dataset_raw_om STRING;
  DECLARE var_table_bd_casos STRING;
  DECLARE var_dataset_bq_omni_izipay_azure STRING;

/*
  DECLARE var_project_operation STRING;
  DECLARE var_project_storage STRING;
  DECLARE var_project_sensitive STRING;
  DECLARE var_dataset_secure_secrets STRING;
  DECLARE var_table_config_protected_data STRING;
  DECLARE var_dataset_raw_stage_om STRING;
  DECLARE var_dataset_raw_om STRING;
  DECLARE var_table_bd_casos STRING;
  DECLARE var_dataset_bq_omni_izipay_azure STRING;
  DECLARE var_fecha_ini DATE;
  DECLARE var_fecha_fin DATE;

  SET var_project_operation = 'dev-izipay-data-operation';
  SET var_project_storage = 'dev-izipay-data-storage';
  SET var_project_sensitive = 'dev-izipay-data-storage';
  SET var_dataset_secure_secrets = 'secure_secrets';
  SET var_table_config_protected_data = 'config_protected_data';
  SET var_dataset_raw_stage_om = 'raw_stage_onemarketer';
  SET var_dataset_raw_om = 'raw_om';
  SET var_table_bd_casos = 'bdcasos';
  SET var_dataset_bq_omni_izipay_azure = 'bq_omni_izipay_azure_saizipaydatamarts';
  */

  
  SET var_dataset_secure_secrets = 'secure_secrets';
  SET var_table_config_protected_data = 'config_protected_data';
  SET var_dataset_raw_stage_om = 'raw_stage_onemarketer';
  SET var_dataset_raw_om = 'raw_onemarketer';
  SET var_table_bd_casos = 'bdcasos';
  SET var_dataset_bq_omni_izipay_azure = 'bq_omni_izipay_azure_saizipaydatamarts';
  SET var_table_tmp_bd_casos = concat('tmp_',var_table_bd_casos);



  /* Verificar si la tabla EXTERNA tiene contenido, guardar el conteo*/
  SET query = """
   select count(1)
   from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_bd_casos||"""`
  """;
  EXECUTE IMMEDIATE(query)
  into cant;

  /* Si la tabla tiene contenido, insertar la data desde la tabla  EXTERNA hacia la tabla en DATA_STORAGE*/
  IF ifnull(cant,0) > 0 

    THEN

      /* Crear una tabla temporal con los datos sumando las columnas adicionales para auditoria*/
      SET query = """
        create or replace table `"""||var_project_operation||"""."""||var_dataset_raw_stage_om||"""."""||var_table_tmp_bd_casos||"""` as
        select
          cast(Prop_0 as string) as visita_id,
          cast(Prop_1 as string) as celular_ejecutivo,
          cast(Prop_2 as string) as fase_caso_final,
          cast(Prop_3 as string) as time_stamp_inicio,
          cast(Prop_4 as string) as time_stamp_final,
          DATE(PARSE_DATE('%Y/%m/%d',LEFT(Prop_3,10)) ) as process_date,
          'One Marketer' as record_source,
          cast(current_datetime('America/Lima') as timestamp) as load_date
        from `"""||var_project_operation||"""."""||var_dataset_bq_omni_izipay_azure||"""."""||var_table_bd_casos||"""` 
      """;
      EXECUTE IMMEDIATE(query);


	    EXECUTE IMMEDIATE """ select min(process_date),max(process_date)
      FROM `"""||var_project_operation||"""."""||var_dataset_raw_stage_om||"""."""||var_table_tmp_bd_casos||"""`
      """
      into var_fecha_ini,var_fecha_fin;
	
      /* Truncar la tabla destino antes de insertar los nuevos datos*/
      SET query = """
      DELETE FROM `"""||var_project_storage||"""."""||var_dataset_raw_om||"""."""||var_table_bd_casos||"""`
      WHERE process_date between '"""||var_fecha_ini||"""' and '"""||var_fecha_fin||"""'  
      """;
      EXECUTE IMMEDIATE(query);

      /* Insertar los datos desde la tabla temporal a la tabla destino*/
      SET query = """
        insert into `"""||var_project_storage||"""."""||var_dataset_raw_om||"""."""||var_table_bd_casos||"""` 
        (
          visita_id,
          celular_ejecutivo,
          fase_caso_final,
          time_stamp_inicio,
          time_stamp_final,
          process_date,
          record_source,
          load_date,
          creation_user
        )
        select
          a.visita_id,
          AEAD.ENCRYPT(pi.key, cast(a.celular_ejecutivo as string), pi.constant) as celular_ejecutivo,
          a.fase_caso_final,
          PARSE_DATETIME('%Y/%m/%d %H:%M:%S',a.time_stamp_inicio) AS time_stamp_inicio,
          PARSE_DATETIME('%Y/%m/%d %H:%M:%S',a.time_stamp_final) AS time_stamp_final ,
          a.process_date,
          a.record_source,
          a.load_date,
          session_user() as creation_user
        from `"""||var_project_operation||"""."""||var_dataset_raw_stage_om||"""."""||var_table_tmp_bd_casos||"""` a
        inner join `"""||var_project_sensitive||"""."""||var_dataset_secure_secrets||"""."""||var_table_config_protected_data||"""` pi on 1=1 and pi.code = 'C_CELL_PHONE' 
      """;
      EXECUTE IMMEDIATE(query);

      /* Eliminar la tabla temporal*/
      SET query = """
        drop table `"""||var_project_operation||"""."""||var_dataset_raw_stage_om||"""."""||var_table_tmp_bd_casos||"""`
      """;
      EXECUTE IMMEDIATE(query);

  END IF;
