          cast(nombrecomercio as string) as nombrecomercio,
          cast(estadocomercio as string) as estadocomercio,
          cast(fechainiciooperacion as string) as fechainiciooperacion,
          cast(calificacionriesgo as string) as calificacionriesgo,
          cast(ubigeo as string) as ubigeo,
          cast(fechahoraregistroaud as string) as fechahoraregistroaud,
