          fechainiciooperacion,
          calificacionriesgo,
          ubigeo,
          fechahoraregistroaud,
          titularid,
          tipoidentificacion,
          process_date,
          record_source,
          load_date,
          creation_user
        )
        select 
          z.party_id_izi,
          codigocomercio,
          AEAD.ENCRYPT(p.key, cast(nombrecomercio as string), p.constant) as nombrecomercio,
          estadocomercio,
          fechainiciooperacion,
          calificacionriesgo,
          ubigeo,
